/* SPDX-License-Identifier: GPL-3.0-only */
/* SMK-37 Bluetooth MIDI (BLE only, no audio): the app side.
 *
 * A separate controller image (ble/ctl: the MPL shim and JieLi's own files, built on the user's
 * computer, never part of this program) sits in the flash block at 0x8B000. This file:
 *   - checks it (header, CRC, entries, RAM window, interrupts) before anything starts it;
 *   - initializes it before audio starts at power-on (its init entry, core 0 in RAM meanwhile, fm1_cpu1.h) and
 *     hands core 1's idle loop its poll entry;
 *   - talks to it only through standard HCI packets in the mailbox rings (x0x_ble_abi.h), with
 *     the BLE-MIDI host (ble/ble_midi_host.c, MPL-2.0, from felucca-bsp);
 *   - puts BLE-MIDI in into the USB MIDI in queue and mirrors the MIDI out (clock, notes) to BLE.
 * With BLUETOOTH OFF, the initialized controller stays idle: no host start, scan or advertising.
 * Without a valid image, core 1 starts as before. Service: the TIMER5 interrupt, next to usb_poll (2 kHz, never inside the render). */
#include "fm1_ble.h"
#include "fm1_supply.h"
#include "ble/ble_midi_host.c"
#include "ble/ble_midi_central.c"
#include "ble/ble_glue.h"

/* All of it in BLERAM (main RAM is full): not cleared at boot, so ble_start sets every field it
 * reads, and nothing reads them before (ble_host_on, in .bss, stays 0 until then). */
#define BLE_OQ 56u                              /* MIDI out to mirror: USB-MIDI packets (SMK pool floor) */
typedef struct {
    xb_mbox_t mb;                               /* first: 64-byte aligned (the rings' cache lines) */
    union { bleh_t h; blec_t c; } host;
    xb_boot_t boot;
    uint8_t fr[XB_FRAME_MAX];                   /* one frame from the controller */
    volatile uint32_t ow, orr;
    uint32_t sysex_drops;
    char nm[9];                                 /* the name it advertises */
} ble_ram_t;
static ble_ram_t ble_r __attribute__((section(".ble_ram"), aligned(64)));
/* attempt 32: the MIDI out mirror in the pool (zeroed at boot), so BLERAM has room for a 64-message
 * MIDI in queue. Written by the audio ISR and read by ble_service, both on core 0. */
static uint32_t ble_oq[BLE_OQ] __attribute__((section(".pool")));
/* core 0's last Bluetooth tick (ms since boot) and core 1's poll count then. In .ble_ram (not
 * cleared): after a watchdog reset, DIAG shows when core 0 stopped and if core 1 still ran. */
static uint32_t ble_alive[2] __attribute__((section(".ble_ram")));
static uint32_t ble_rails[2] __attribute__((section(".ble_ram")));   /* attempt 27: before, after the stock supply setup
                                                                      * (CON5 | CON6 << 8 | CON9 << 16 | CON0 << 24) */

static void ble_record(void);
static uint8_t ble_central_role;                 /* active role; changed only by TIMER5 after the old role stops */
/* attempt 34 (DIAG): interval | end reason << 16 | pairing refusals << 24;
 * MIDI in drops | asked MTU << 8 (10 bits) | request sent << 18 | result << 19 | latency << 21 (3) | L2CAP requests << 24 */
static uint32_t ble_sat(uint32_t v, uint32_t m) { return v > m ? m : v; }
extern uint32_t smc_rx_diag(void);
static uint32_t ble_h_link0(void)
{
    if (ble_central_role) return (uint32_t)ble_r.host.c.rx_acl | (uint32_t)ble_r.host.c.rx_notify << 8 |
                                 (uint32_t)ble_r.host.c.rx_midi << 16 | (uint32_t)ble_r.host.c.rx_reject << 24;
    return ble_r.host.h.conn_int | (uint32_t)ble_r.host.h.disc_reason << 16 | ble_sat(ble_r.host.h.smp_rejects, 255u) << 24;
}
static uint32_t ble_h_link1(void)
{
    if (ble_central_role) return smc_rx_diag();
    return ble_sat(ble_r.host.h.drops_in, 255u) | ble_sat(ble_r.host.h.mtu_req, 1023u) << 8 | (uint32_t)(ble_r.host.h.cpu_state & 1u) << 18 |
           (uint32_t)(ble_r.host.h.cpu_result & 3u) << 19 | ble_sat(ble_r.host.h.conn_lat, 7u) << 21 | (uint32_t)ble_r.host.h.sig_reqs << 24;
}
static uint8_t ble_img = BLE_IMG_NONE, ble_boot_on, ble_up, ble_want, ble_host_on, ble_dead, ble_blocked;
extern int smc_ble_role_get(void);
extern void smc_ble_midi(const uint8_t *msg, uint8_t len);
extern void smc_ble_link(int up);
extern void smc_mmc_host(uint8_t cmd, uint8_t src);
static uint32_t ble_ok_at;                      /* fm1_ms when the controller became READY */
/* the start guard (ble_glue.h): survives a reset, so a start that crashes or freezes the unit is not
 * tried again at the next power-on */
ble_guard_t ble_guard __attribute__((section(".noinit")));
extern uint32_t _ram_sink[], _ram_sink_end[];   /* app.ld: 1 KiB at 0x01C00000 that nothing uses */
#define BLE_SINK_FILL(i) (0x5A17C0DEu ^ ((i) * 0x01010101u))
static void ble_sink_fill(void)
{
    uint32_t i, n = (uint32_t)(_ram_sink_end - _ram_sink);
    for (i = 0; i < n; i++)
        _ram_sink[i] = BLE_SINK_FILL(i);
}
/* how many words of the sink changed since ble_sink_fill: a write by the radio (or its DMA) */
/* core 0's record of its start wait (fm1_cpu1.h), kept in the guard */
static void ble_wait_record(void)
{
    uint32_t i;
    ble_guard.wait_ms = fm1_c1_wait_ms;
    for (i = 0; i < 4u; i++)
        ble_guard.seen[i] = fm1_c1_wait_seen[i];
    ble_guard.code_bad = fm1_c1_sum_bad;
    ble_guard.code_sum = fm1_c1_sum_got;
}
static void ble_sink_check(void)
{
    uint32_t i, n = (uint32_t)(_ram_sink_end - _ram_sink), bad = 0;
    for (i = 0; i < n; i++)
        if (_ram_sink[i] != BLE_SINK_FILL(i)) {
            if (!bad++) {
                ble_guard.sink_at = (uint32_t)(uintptr_t)&_ram_sink[i];
                ble_guard.sink_val = _ram_sink[i];
            }
        }
    ble_guard.sink_n = bad;
}

static int ble_send(uint8_t t, const uint8_t *p, uint16_t n, void *ctx)
{
    (void)ctx;
    return xb_frame_put(&ble_r.mb.h2c, t, p, n);
}
/* attempt 29: the APC40 mkII identity and introduction over Bluetooth (Loopy Pro on a BLE port), as
 * usb.c does on USB. Other SysEx from Bluetooth is not taken (counted). */
extern uint8_t smk_apc_usb_event(uint32_t pkt);
extern void smk_apc_ble_host_seen(void);
extern void smk_apc_host_generic(uint8_t ble);
extern void smk_apc_ble_link(uint8_t connected, uint8_t notifying);
extern uint8_t smk_apc_ble_event(uint32_t pkt, uint8_t notifying);
extern void smk_inlog(uint32_t src, uint32_t pkt);   /* a76: the inbound recorder (main_fm1.c) */
static uint8_t ble_sx[16], ble_sx_n, ble_sx_over, ble_sx_reply, ble_sx_ch;
static void ble_sysex_in(const uint8_t *p, uint32_t n, int end, void *ctx)
{
    (void)ctx;
    if (!ble_want || smc_ble_role_get()) {
        ble_sx_n = ble_sx_over = ble_sx_reply = 0;
        return;                                 /* discard the old device link on OFF or role change */
    }
    if (!end) {
        while (n--) {
            if (ble_sx_n < sizeof ble_sx) ble_sx[ble_sx_n++] = *p++;
            else ble_sx_over = 1;
        }
        return;
    }
    if (end > 0 && !ble_sx_over && ble_sx_n == 4u && ble_sx[0] == 0x7Eu && ble_sx[2] == 0x06u &&
        ble_sx[3] == 0x01u && (ble_sx[1] <= 0x0Fu || ble_sx[1] == 0x7Fu)) {
        ble_sx_ch = ble_sx[1];                    /* Universal Device Inquiry */
        ble_sx_reply = 1;
        smk_apc_ble_host_seen();
    } else if (end > 0 && !ble_sx_over && ble_sx_n == 10u && ble_sx[0] == 0x47u && ble_sx[1] == 0x7Fu &&
               ble_sx[2] == 0x29u && ble_sx[3] == 0x60u && ble_sx[4] == 0x00u && ble_sx[5] == 0x04u &&
               (ble_sx[6] == 0x40u || ble_sx[6] == 0x41u || ble_sx[6] == 0x42u)) {
        ble_sx_reply = 2;                         /* the APC40 mkII introduction */
        smk_apc_ble_host_seen();
        if (ble_sx[6] == 0x40u)
            smk_apc_host_generic(1u);             /* CLP-18: generic mode: the Bluetooth host feedback ends */
    } else if (end > 0 && !ble_sx_over && ble_sx_n == 4u && ble_sx[0] == 0x7Fu && ble_sx[1] == 0x7Fu &&
               ble_sx[2] == 0x06u && ble_sx[3] >= 1u && ble_sx[3] <= 43u) {
        smc_mmc_host(ble_sx[3], 1u);
    } else if (end)
        ble_r.sysex_drops++;
    ble_sx_n = 0;
    ble_sx_over = 0;
}
static void ble_sx_answer(bleh_t *h)
{
    uint8_t m[35];
    uint32_t i, n;
    if (!ble_sx_reply || !bleh_notifying(h))
        return;
    for (i = 0; i < sizeof m; i++) m[i] = 0;
    if (ble_sx_reply == 1u) {                     /* the same reply as usb.c apc40_device_inquiry */
        m[0] = 0xF0; m[1] = 0x7E; m[2] = ble_sx_ch; m[3] = 0x06; m[4] = 0x02;
        m[5] = 0x47; m[6] = 0x29; m[7] = 0x00; m[8] = 0x19;
        m[9] = 0x01; m[10] = 0x02; m[13] = 0x7F;
        m[34] = 0xF7;
        n = 35u;
    } else {                                      /* usb.c apc40_introduction_reply */
        m[0] = 0xF0; m[1] = 0x47; m[2] = 0x7F; m[3] = 0x29; m[4] = 0x61; m[5] = 0x00; m[6] = 0x09;
        m[16] = 0xF7;
        n = 17u;
    }
    if (bleh_sysex_send(h, m, n, (uint16_t)(fm1_ms & 0x1FFFu)) != -2)
        ble_sx_reply = 0;                         /* sent (or refused): busy only waits */
}

/* Initialize a valid, unblocked controller before audio, even when OFF. RF trim cannot
 * safely run from a live UI setter. Only TIMER5 starts the requested host/radio role. */
static void ble_prepare(int on)
{
    const xb_header_t *h = FM1_BLE_HDR;
    fm1_t5w_boot();                             /* before TIMER5 starts: keep the last boot's frame watch */
    ble_img = (uint8_t)ble_img_check(FM1_BLE_IMG, XB_FLASH_SIZE, XB_FLASH_XIP);
    ble_want = (uint8_t)(on != 0);
    ble_central_role = (uint8_t)(smc_ble_role_get() != 0);
    if (ble_guard.magic == BLE_GUARD_MAGIC && ble_guard.trying) {
        if (ble_r.mb.magic == XB_MBOX_MAGIC)
            ble_record();                       /* the start that reset the unit: its mailbox (BLERAM) */
        ble_sink_check();                       /* (the boot may have used that RAM too) */
        ble_guard.sink_n |= 0x80000000u;        /* bit 31: checked at the next boot, not after the init */
        ble_guard.reset = fm1_boot.p3_rst | (fm1_boot.rst_src & 0xFFFFFFu) << 8;   /* what reset it */
        ble_guard.wait_end = fm1_c1_wait_end;   /* how core 0's wait ended (RAM code) */
        ble_wait_record();
    }
    if (!ble_guard_boot(&ble_guard, ble_img == BLE_IMG_OK, 1)) {
        if (ble_img == BLE_IMG_OK && ble_guard.blocked) {
            ble_blocked = 1;                    /* the last start failed: not now (STATUS FAILED) */
            ble_dead = 1;
        }
        return;
    }
    ble_boot_on = 1;
    fm1_cpu1_ble_stacks(h->isr_stack_hi, h->ram_lo);
    fm1_guard_xip_hi = XB_FLASH_XIP + XB_FLASH_SIZE - 1u;
    fm1_guard_ram_hi = h->ram_hi;
}

/* power-on, after core 1 started and before the audio and TIMER5: run the image's init on core 1
 * with core 0 in RAM (the controller's RF trim), then hand core 1 its poll entry */
/* The controller's init runs on core 0 at power-on, before core 1 starts (one core runs, as in
 * fm1-ctl). Tests 1-11 ran it on core 1 while core 0 waited in RAM: core 0 stopped about 48 ms
 * into every start (in the TX IQ trim), with its RAM code unchanged; core 1 then went on to READY.
 * ble_attach hands the controller to core 1 after plat_cpu2_set. */
static uint8_t ble_c0_ready;
static void ble_central_link_notify(int up);
static void ble_central_midi(const uint8_t *p, uint8_t n, void *ctx)
{
    (void)ctx;
    /* Subscription completion and the first MIDI notification can arrive
     * within one TIMER5 receive batch. Publish the new connection boundary
     * BEFORE enqueueing that packet; the late service-level notification
     * would otherwise cut away genuine new-session controls. */
    if (ble_want && smc_ble_role_get() && blec_connected(&ble_r.host.c))
        ble_central_link_notify(1);
    /* Reuse the bounded ISR-owned INLOG ring; MMC records command in d1. */
    if (n == 3u)
        smk_inlog(4u, (uint32_t)p[0] << 8 | (uint32_t)p[1] << 16 | (uint32_t)p[2] << 24);
    else if (n == 6u)
        smk_inlog(4u, (uint32_t)p[0] << 8 | (uint32_t)p[4] << 16);
    /* TIMER5: stop old-role input as soon as a role change is requested. */
    if (ble_want && smc_ble_role_get()) smc_ble_midi(p, n);
}
static void ble_start(void)
{
    const xb_header_t *h = FM1_BLE_HDR;
    xb_mbox_t *mb = &ble_r.mb;
    int rc;
    uint32_t bus, stk, top;
    uint8_t addr[6];
    {
        static const uint8_t none[1] = {0};
        if (flash_ok)                           /* the factory record (USRTRIM): one address per unit */
            ble_addr_of(fm1_xip_ptr(SMK_TRIM_FLASH), 0x22Cu, addr, ble_r.nm);
        else
            ble_addr_of(none, 1u, addr, ble_r.nm);
    }
    ble_r.ow = ble_r.orr = 0;
    ble_r.sysex_drops = 0;
    ble_c0_ready = 0;
    if (!ble_boot_on)
        return;
    {
        uint8_t *z = (uint8_t *)mb;
        uint32_t i;
        for (i = 0; i < sizeof *mb; i++)
            z[i] = 0;
    }
    mb->magic = XB_MBOX_MAGIC;
    mb->abi = XB_ABI;
    xb_ring_init(&mb->h2c);
    xb_ring_init(&mb->c2h);
    fm1_ble_boot_fill(&ble_r.boot, mb);
    if (ble_central_role)
        blec_init(&ble_r.host.c, ble_send, ble_central_midi, 0, addr);
    else {
        bleh_init(&ble_r.host.h, ble_send, 0, ble_r.nm, addr);
        bleh_set_sysex(&ble_r.host.h, ble_sysex_in);
    }
    fm1_ble_sync();
    ble_guard.start_ms = fm1_ms;
    ble_guard.sink_n = ble_guard.sink_at = ble_guard.sink_val = ble_guard.wait_end = 0;
    ble_guard.xosc_pre = fm1_ble_xosc();
    ble_guard.xosc_post = 0;
    ble_sink_fill();
    fm1_guard_enable(FM1_GUARD_PC);             /* the PC windows with the image's flash and RAM (ble_prepare) */
    bus = fm1_guard_bus_pause();                /* JieLi's RF code: not for the bus-invalid checks */
    top = (uint32_t)fm1_guard_top_locked();
    if (top)
        fm1_guard_unlock_top();                 /* request_irq writes the vectors */
    fm1_wdt_feed();                             /* init takes about 0.6 s of the 8 s */
    {   /* attempt 27: the stock supply setup (DCDC13, VDC14 1.60 V, SYSVDD 1.38 V) before the RF init */
        uint32_t f = irq_save();
        ble_rails[0] = fm1_rails_read() | (uint32_t)fm1_p33_read(0x00u) << 24;
        (void)fm1_supply_stock();               /* its read-back: rails[1] (DIAG) */
        ble_rails[1] = fm1_rails_read() | (uint32_t)fm1_p33_read(0x00u) << 24;
        irq_restore(f);
    }
    {
        uint32_t f = irq_save(), t0 = fm1_ticks();
        stk = fm1_guard_stack_pause();          /* the image's run stack */
        rc = fm1_ble_init_here(h->init, &ble_r.boot);
        fm1_guard_stack_resume(stk);
        ble_guard.init_ms = (fm1_ticks() - t0) / (FM1_TICKS_PER_US * 1000u);
        irq_restore(f);
    }
    if (top)
        fm1_guard_lock_top();
    fm1_wdt_feed();
    ble_guard.xosc_post = fm1_ble_xosc();
    ble_record();
    ble_sink_check();
    ble_guard_started(&ble_guard, 0, rc == 0 && mb->state == XB_ST_READY);
    if (rc != 0 || mb->state != XB_ST_READY) {
        fm1_guard_bus_resume(bus);
        ble_dead = 1;
        return;
    }
    ble_c0_ready = 1;                           /* the bus-invalid checks stay off while it runs */
}

#ifndef X0X_RAM_CANARY
#define X0X_RAM_CANARY 0  /* 1: arm the test-26 RAM canary (0x01C72000-0x01C74000, test builds only) */
#endif

/* after plat_cpu2_set: core 1 runs the controller from now on (its interrupts, its poll) */
static void ble_attach(void)
{
    const xb_header_t *h = FM1_BLE_HDR;
    if (!ble_c0_ready)
        return;
    if (!fm1_c1_on) {                           /* one core (fm1-x0x#10): no Bluetooth */
        ble_guard.trying = 0;                   /* not the controller's fault: no block */
        fm1_guard_bus_resume(FM1_GUARD_BUS_BITS);
        ble_dead = 1;
        return;
    }
    fm1_guard_watch_c0_stacks();               /* test 21: who changes core 0's interrupt stack */
    fm1_t5w_arm = 1;                            /* test 23: the timer 5 frame closed to all writers */
#if X0X_RAM_CANARY
    /* Test 26: the RAM canary, core 1 watches it. Test builds only: the area
     * overlaps the end of .pool when less than 8 KiB of the pool is free. */
    for (uint32_t *cw = (uint32_t *)(uintptr_t)FM1_CAN_LO; cw < (uint32_t *)(uintptr_t)FM1_CAN_HI; cw++)
        *cw = 0xFFFFFFFFu;
    fm1_can.n = fm1_can.scans = 0;
    fm1_can.armed = 0xCA9A11E5u;
#else
    fm1_can.armed = 0;                          /* .ble_ram survives a reset: clear an old arm */
#endif
    fm1_c0_dead.magic = 0;                      /* test 24: core 1 watches core 0's clock */
    fm1_c0_dead.n = 0;
    fm1_ble_sync();
    fm1_c1_c0_clock = &fm1_ms;
    fm1_c1_mb.poll = (void (*)(void))(uintptr_t)h->poll;
    fm1_ble_sync();
    ble_ok_at = fm1_ms;
    ble_up = 1;
}

/* the image's start record and the mailbox, kept in the guard (ED_DIAG reads it) */
static void ble_record(void)
{
    uint32_t i;
    fm1_ble_sync();
    ble_guard.mb_state = ble_r.mb.state;
    ble_guard.mb_err = ble_r.mb.err;
    for (i = 0; i < 6u; i++)
        ble_guard.dbg[i] = ble_r.mb.dbg[i];
}

/* CIN 8 / CIN 9 vel0 — same release class as usb.c midi_pkt_is_note_off. */
static int ble_out_is_note_off(uint32_t pkt)
{
    uint32_t cin = pkt & 0xFu;
    return cin == 8u || (cin == 9u && ((pkt >> 24) & 0x7Fu) == 0u);
}

/* USB-MIDI single-byte realtime transport (CIN 0xF): Start/Continue/Stop.
 * Mirror usb.c midi_pkt_is_rt_transport on the BLE out ring. */
static int ble_out_is_rt_transport(uint32_t pkt)
{
    uint32_t st;
    if ((pkt & 0xFu) != 0xFu)
        return 0;
    st = (pkt >> 8) & 0xFFu;
    return st == 0xFAu || st == 0xFBu || st == 0xFCu;
}

static int ble_out_pkt_is_keep(uint32_t pkt)
{
    return ble_out_is_note_off(pkt) || ble_out_is_rt_transport(pkt);
}

/* the audio ISR (single producer): mirror one MIDI out packet */
static void ble_out(uint32_t pkt)
{
    uint32_t i, pass, ww, rr;
    if (ble_central_role || smc_ble_role_get() || !ble_want ||
        !ble_host_on || !bleh_notifying(&ble_r.host.h))
        return;
    ww = ble_r.ow;
    rr = ble_r.orr;
    if (ww - rr < BLE_OQ) {
        ble_oq[ww % BLE_OQ] = pkt;
        RING_PUBLISH();
        ble_r.ow = ww + 1u;
        return;
    }
    /* Full BLE out mirror: drop CCs under notify backpressure; never drop Note Off
     * or Start/Continue/Stop (stuck note / sticky transport into Loopy over BLE). */
    if (!ble_out_pkt_is_keep(pkt))
        return;
    for (pass = 0; pass < 2u; pass++) {
        for (i = rr; i != ww; i++) {
            uint32_t p = ble_oq[i % BLE_OQ];
            if (ble_out_pkt_is_keep(p))
                continue;
            if (pass == 0u && (p & 0xFu) != 0xBu)
                continue;
            ble_oq[i % BLE_OQ] = pkt;
            RING_PUBLISH();
            return;
        }
    }
}

static void ble_fail(void)
{
    fm1_guard_bus_resume(FM1_GUARD_BUS_BITS);   /* the controller stops: the app's checks again */
    fm1_c1_mb.poll = 0;                         /* core 1 stops calling it */
    fm1_ble_sync();
    fm1_cpu1_irqs_off();
    ble_up = 0;
    ble_host_on = 0;
    ble_dead = 1;
}

/* BLE-16, MID-15: when the link ends, usb.c midi_link_check puts one PLAT_MIDI_LINK_END(1) into the MIDI in
 * queue. The engine then releases the notes that came from Bluetooth and the clock of Bluetooth. It goes after
 * the MIDI in of this tick, so no note of the old link comes after it. */
static uint8_t ble_link_st;
static uint8_t ble_central_link_seen;
static void ble_central_link_notify(int up)
{
    uint8_t next = (uint8_t)(up != 0);
    if (next != ble_central_link_seen) {
        ble_central_link_seen = next;
        smc_ble_link(next);
    }
}

/* SMC central: HCI, ATT and MIDI run in TIMER5 beside the original peripheral host. */
static void ble_central_service(void)
{
    blec_t *c = &ble_r.host.c;
    uint32_t k;
    uint8_t t;
    int want = ble_want && smc_ble_role_get();
    if (!ble_up) { ble_central_link_notify(0); return; }
    if (ble_r.mb.state != XB_ST_READY || !fm1_c1_on) {
        ble_record(); ble_fail(); ble_central_link_notify(0); return;
    }
    ble_alive[0] = fm1_ms;
    ble_alive[1] = ble_r.mb.polls;
    if (ble_guard.trying && fm1_ms - ble_ok_at > BLE_GUARD_OK_MS)
        ble_guard_ok(&ble_guard);
    if (!ble_host_on) {
        if (!want) return;
        ble_host_on = 1;
    }
    /* Stop can submit Disconnect before receive or poll supplies the current time. */
    c->now_ms = fm1_ms;
    if (!want && c->state != BLEC_OFF && c->state != BLEC_STOPPING)
        blec_stop(c);
    for (k = 0; k < 8u; k++) {
        int n = xb_frame_get(&ble_r.mb.c2h, &t, ble_r.fr, sizeof ble_r.fr);
        if (n == 0) break;
        if (n > 0) blec_rx(c, t, ble_r.fr, (uint16_t)n, fm1_ms);
    }
    if (!want) {
        blec_poll(c, fm1_ms); /* finish disable/cancel/disconnect while radio is OFF */
        ble_central_link_notify(0);
        return;
    }
    if (c->state == BLEC_STOPPING) {
        blec_poll(c, fm1_ms);
        ble_central_link_notify(0);
        return;
    }
    if (c->state == BLEC_OFF) {
        /* Drain old HCI events before a fresh Reset starts a new command sequence. */
        if (xb_ring_used(&ble_r.mb.c2h)) return;
        blec_start(c, fm1_ms);
    }
    blec_poll(c, fm1_ms);
    ble_central_link_notify(want && blec_connected(c));
}

/* TIMER5, next to usb_poll (same context: the MIDI in queue has one writer) */
static void ble_device_service(void)
{
    bleh_t *h = &ble_r.host.h;
    uint32_t k;
    uint8_t t;
    bleh_msg_t m;
    int want = ble_want && !smc_ble_role_get();
    if (!ble_up) {
        midi_link_check(&ble_link_st, 0u, 1u);   /* (after a failure: the release, when the queue has room) */
        return;
    }
    if (ble_r.mb.state != XB_ST_READY || !fm1_c1_on) {
        ble_record();
        ble_fail();
        midi_link_check(&ble_link_st, 0u, 1u);
        return;
    }
    ble_alive[0] = fm1_ms;
    ble_alive[1] = ble_r.mb.polls;
    if (ble_guard.trying && fm1_ms - ble_ok_at > BLE_GUARD_OK_MS)
        ble_guard_ok(&ble_guard);               /* it ran: the next power-on starts it again */
    if (!ble_host_on) {
        if (!want)
            return;                             /* OFF since power-on: the host never starts */
        ble_host_on = 1;
        bleh_start(h);
    }
    bleh_radio(h, want);
    for (k = 0; k < 8u; k++) {                  /* events and data from the controller */
        int n = xb_frame_get(&ble_r.mb.c2h, &t, ble_r.fr, sizeof ble_r.fr);
        if (n == 0)
            break;
        if (n > 0) {
            bleh_rx(h, t, ble_r.fr, (uint16_t)n);
        }
    }
    if (!want) {
        /* End the old input on OFF or role change, even with a full MIDI queue.
         * Discard feedback and output from this link while Disconnect completes. */
        h->q_r = h->q_w; h->in_r = h->in_w; h->sx_on = 0;
        ble_r.orr = ble_r.ow;
        ble_sx_n = ble_sx_over = ble_sx_reply = ble_sx_ch = 0;
        smk_apc_ble_link(0, 0);
        bleh_poll(h);
        midi_link_check(&ble_link_st, 0u, 1u);
        return;
    }
    smk_apc_ble_link((uint8_t)bleh_connected(h), (uint8_t)bleh_notifying(h));   /* a71: Loopy gone: clip feedback off */
    while (ble_r.orr != ble_r.ow) {             /* MIDI out, mirrored */
        uint8_t b[3];
        uint32_t len = ble_msg_of_usb(ble_oq[ble_r.orr % BLE_OQ], b);
        if (len && bleh_notifying(h) && bleh_midi_send(h, b, (uint8_t)len, (uint16_t)(fm1_ms & 0x1FFFu)) == -2)
            break;                              /* the host's queue is full: next tick */
        ble_r.orr++;
    }
    smk_inlog(2u, (uint32_t)((bleh_connected(h) ? 1u : 0u) | (bleh_notifying(h) ? 2u : 0u)) << 24);   /* a76: edges */
    ble_sx_answer(h);
    /* attempt 37: no parameter request (test 34's, accepted by the iPhone, came with a huge MIDI delay) */
    bleh_poll(h);
    /* MIDI in: same midi_in_q as USB/TRS. Cap MQ pulls/tick (BLE-08). Note Off never
     * drops when the ring is full of CCs — midi_in_put displaces (usb.c). */
    for (uint32_t n = 0; n < MQ && bleh_midi_next(h, &m); n++) {
        uint32_t pkt = ble_usb_of_msg(&m);
        if (pkt && ((pkt & 0xFu) == 8u || (pkt & 0xFu) == 9u || (pkt & 0xFu) == 0xBu) &&
            smk_apc_ble_event(pkt, (uint8_t)bleh_notifying(h)))   /* a76: notify off: no pad colour */
            continue;                             /* attempt 29: APC clip and transport feedback, as on USB */
        if (pkt)
            (void)midi_in_put(pkt | 0x10u);         /* cable bits: the input, 1 Bluetooth (MID-15) */
    }
    midi_link_check(&ble_link_st, (uint32_t)bleh_connected(h), 1u);
}

#include "ble/ble_role.h"

int plat_ble_state(void)
{
    if (ble_img == BLE_IMG_NONE)
        return PLAT_BLE_NOIMG;
    if (ble_img == BLE_IMG_BAD)
        return PLAT_BLE_BADIMG;
    if (!ble_want)
        return PLAT_BLE_OFF;
    if (ble_dead || !ble_boot_on)
        return PLAT_BLE_FAILED;
    if (!ble_host_on || ble_role_changing || ble_central_role != (uint8_t)(smc_ble_role_get() != 0))
        return PLAT_BLE_STARTING;
    if (ble_central_role) {
        if (!ble_up || ble_r.host.c.state == BLEC_STARTING) return PLAT_BLE_STARTING;
        if (ble_r.host.c.state == BLEC_FAILED) return PLAT_BLE_FAILED;
        return blec_connected(&ble_r.host.c) ? PLAT_BLE_CONNECTED : PLAT_BLE_READY;
    }
    if (!ble_up || ble_r.host.h.state == BLEH_STARTING || ble_r.host.h.state == BLEH_IDLE)
        return PLAT_BLE_STARTING;
    if (ble_r.host.h.state == BLEH_ERROR)
        return PLAT_BLE_FAILED;
    return bleh_connected(&ble_r.host.h) ? PLAT_BLE_CONNECTED : PLAT_BLE_READY;
}
const char *plat_ble_name(void)
{
    return ble_central_role ? (ble_r.host.c.link_name[0] ? (const char *)ble_r.host.c.link_name : "SMC-Mixer") : ble_r.nm;
}
int plat_ble_smc_send(const uint8_t *msg, uint8_t len)
{
    uint32_t f = irq_save();
    int sent = ble_central_role && smc_ble_role_get() && ble_up && ble_host_on && ble_want &&
               blec_midi_send(&ble_r.host.c, msg, len);
    irq_restore(f);                             /* TIMER5 must not replace the host union mid-enqueue */
    return sent;
}
void plat_ble_set(int on)
{
    ble_want = (uint8_t)(on != 0);
    /* OFF arms a retry at the next boot, never re-enters RF init during audio.
     * Keep this boot's failure latch: ON must report FAILED, not a false READY. */
    if (!on && ble_guard.blocked)
        ble_guard_user_off(&ble_guard);
}

/* ED_DIAG (editor.c): the start guard and the controller's state, as 32-bit words */
static uint32_t ble_diag(uint32_t *w, uint32_t max)
{
    uint32_t n = 0, i;
    const uint32_t *g = (const uint32_t *)&ble_guard;
    for (i = 0; i < sizeof ble_guard / 4u && n < max; i++)
        w[n++] = g[i];
    if (n + 17u > max)
        return n;
    w[n++] = ble_img | (uint32_t)ble_boot_on << 8 | (uint32_t)ble_up << 16 | (uint32_t)ble_dead << 24;
    w[n++] = ble_want | (uint32_t)ble_host_on << 8 | (uint32_t)ble_blocked << 16 | (uint32_t)fm1_c1_on << 24;
    w[n++] = fm1_c1_gave_up;
    w[n++] = (uint32_t)plat_ble_state();
    w[n++] = ble_r.mb.state;                    /* raw: after a reset, the last start's */
    w[n++] = ble_r.mb.err;
    w[n++] = ble_r.mb.polls;
    w[n++] = fm1_c1_mb.poll_max;
    w[n++] = ble_central_role ? ble_r.host.c.state : ble_r.host.h.state;
    w[n++] = fm1_c1_trace;
    w[n++] = fm1_boot.p3_rst | (fm1_boot.rst_src & 0xFFFFFFu) << 8;   /* this boot's reset */
    if (n + 6u > max)
        return n;
    w[n++] = ble_r.mb.h2c.head | ble_r.mb.h2c.tail << 16;   /* the HCI rings: written, read */
    w[n++] = ble_r.mb.c2h.head | ble_r.mb.c2h.tail << 16;
    w[n++] = ble_r.mb.c2h_drops;
    w[n++] = ble_central_role ? (uint32_t)ble_r.host.c.step | (uint32_t)ble_r.host.c.waiting << 8 |
                                 (uint32_t)ble_r.host.c.credits << 16 |
                                 (uint32_t)ble_r.host.c.rx_reason << 24 | 0x80000000u :
                                 (uint32_t)ble_r.host.h.step | (uint32_t)ble_r.host.h.cmd_wait << 8 |
                                 (uint32_t)ble_r.host.h.credits << 16;
    w[n++] = ble_r.mb.dbg[XB_DBG_INIT_MS];     /* frames the controller took */
    w[n++] = ble_r.mb.dbg[XB_DBG_MS];          /* frames it gave to the app */
    if (n + 2u > max)
        return n;
    w[n++] = ble_h_link0();                                 /* attempt 34: interval, latency in use */
    w[n++] = ble_h_link1();                                 /* MIDI in drops, request state and result */
    if (n + 4u > max)                                       /* a76: 4 words follow (was 2: one word past w[]) */
        return n;
    w[n++] = ble_alive[0];
    w[n++] = ble_alive[1];
    w[n++] = ble_rails[0];
    w[n++] = ble_rails[1];
    if (n + 6u > max)
        return n;
    /* Versioned tail, present in both roles; central fields are valid only in central role. */
    w[n++] = 0x534D4301u;
    w[n++] = ble_central_role ? ble_r.host.c.midi_handle | (uint32_t)ble_r.host.c.cccd_handle << 16 : 0;
    w[n++] = ble_central_role ? blec_rd16(ble_r.host.c.reject_head) |
                               (uint32_t)blec_rd16(ble_r.host.c.reject_head + 2) << 16 : 0;
    w[n++] = ble_central_role ? blec_rd16(ble_r.host.c.reject_head + 4) |
                               (uint32_t)blec_rd16(ble_r.host.c.reject_head + 6) << 16 : 0;
    w[n++] = ble_central_role ? ble_r.host.c.reject_n | (uint32_t)ble_r.host.c.reject_reason << 16 |
                               (uint32_t)ble_r.host.c.att_op << 24 : 0;
    w[n++] = ble_central_role ? ble_r.host.c.att_handle | (uint32_t)ble_r.host.c.att_waiting << 16 : 0;
    return n;
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""FP-001: dual-digest evidence must not conflate source FP with served HTML."""
import io
import json
import tempfile
import unittest
from pathlib import Path
from unittest import mock

TOP = Path(__file__).resolve().parents[2]
import sys

sys.path.insert(0, str(TOP / "tools"))
import check_installer_digests as digests  # noqa: E402

SOURCE = "8caf87247afb79dda2107f3074d73da7f2512f5d14e55db32b9285baadc38157"
SERVED = "66b56ba5accd1309664320c91db52c28438080a97b2bdb3fa31f6b830f3ca554"
OTHER = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"


class DualDigest(unittest.TestCase):
    def good(self, **extra):
        data = {
            "schema": 1,
            "installer_source_fingerprint": SOURCE,
            "served_install_html_sha256": SERVED,
        }
        data.update(extra)
        return data

    def test_pass_with_separate_fields(self):
        result = digests.check_evidence(self.good())
        self.assertTrue(result["ok"])
        self.assertEqual(result["installer_source_fingerprint"], SOURCE)
        self.assertEqual(result["served_install_html_sha256"], SERVED)
        self.assertIsNone(result["fetched_install_html_sha256"])

    def test_pass_with_installer_sha256_alias_matching_source(self):
        result = digests.check_evidence(self.good(installer_sha256=SOURCE))
        self.assertTrue(result["ok"])

    def test_fail_when_alias_does_not_match_source(self):
        with self.assertRaisesRegex(
            digests.DigestCheckError, "alias must equal installer_source_fingerprint"
        ):
            digests.check_evidence(self.good(installer_sha256=SERVED))

    def test_fail_when_source_equals_served(self):
        with self.assertRaisesRegex(digests.DigestCheckError, "must not equal"):
            digests.check_evidence(
                self.good(
                    installer_source_fingerprint=SOURCE,
                    served_install_html_sha256=SOURCE,
                )
            )

    def test_fail_missing_served_field(self):
        evidence = {
            "schema": 1,
            "installer_source_fingerprint": SOURCE,
        }
        with self.assertRaisesRegex(digests.DigestCheckError, "served install HTML"):
            digests.check_evidence(evidence)

    def test_fail_installer_sha256_alone(self):
        evidence = {"schema": 1, "installer_sha256": SOURCE}
        with self.assertRaisesRegex(digests.DigestCheckError, "conflates"):
            digests.check_evidence(evidence)

    def test_fail_legacy_installer_fp_without_dual_fields(self):
        evidence = {"schema": 1, "installer_fp": SOURCE}
        with self.assertRaisesRegex(digests.DigestCheckError, "conflated field"):
            digests.check_evidence(evidence)

    def test_fail_explicit_single_pin_claim(self):
        with self.assertRaisesRegex(digests.DigestCheckError, "single Installer FP"):
            digests.check_evidence(self.good(installer_fp_equals_both=True))

    def test_fail_when_html_bytes_mismatch(self):
        html = b"<html>not the recorded digest</html>"
        with self.assertRaisesRegex(
            digests.DigestCheckError, "does not match fetched install HTML"
        ):
            digests.check_evidence(self.good(), html_bytes=html)

    def test_pass_when_html_bytes_match(self):
        html = b"exact-bytes-for-served-digest"
        served = digests.sha256_bytes(html)
        evidence = self.good(served_install_html_sha256=served)
        # source must differ
        evidence["installer_source_fingerprint"] = SOURCE
        self.assertNotEqual(SOURCE, served)
        result = digests.check_evidence(evidence, html_bytes=html)
        self.assertEqual(result["fetched_install_html_sha256"], served)

    def test_fetch_compares_served_digest(self):
        html = b"<html id=install></html>"
        served = digests.sha256_bytes(html)
        evidence = self.good(served_install_html_sha256=served)

        class Resp(io.BytesIO):
            status = 200

            def __enter__(self):
                return self

            def __exit__(self, *args):
                return False

        def fake_open(req, timeout=60):
            self.assertIn("install", req.full_url)
            return Resp(html)

        with mock.patch.object(digests.urllib.request, "urlopen", fake_open):
            result = digests.check_evidence(
                evidence, fetch_url="https://example.test/install/"
            )
        self.assertEqual(result["fetched_install_html_sha256"], served)

    def test_fetch_mismatch_fails(self):
        evidence = self.good()

        class Resp(io.BytesIO):
            status = 200

            def __enter__(self):
                return self

            def __exit__(self, *args):
                return False

        def fake_open(req, timeout=60):
            return Resp(b"wrong-html")

        with mock.patch.object(digests.urllib.request, "urlopen", fake_open):
            with self.assertRaisesRegex(
                digests.DigestCheckError, "does not match fetched install HTML"
            ):
                digests.check_evidence(
                    evidence, fetch_url="https://example.test/install/"
                )

    def test_expect_source_mismatch(self):
        with self.assertRaisesRegex(digests.DigestCheckError, "expect_source"):
            digests.check_evidence(self.good(), expect_source=OTHER)

    def test_cli_pass_and_fail(self):
        with tempfile.TemporaryDirectory() as tmp:
            path = Path(tmp) / "digests.json"
            path.write_text(json.dumps(self.good()) + "\n", encoding="utf-8")
            with mock.patch("sys.stdout", new=io.StringIO()), mock.patch(
                "sys.stderr", new=io.StringIO()
            ):
                self.assertEqual(digests.main([str(path)]), 0)
            bad = Path(tmp) / "bad.json"
            bad.write_text(
                json.dumps({"schema": 1, "installer_sha256": SOURCE}) + "\n",
                encoding="utf-8",
            )
            with mock.patch("sys.stdout", new=io.StringIO()), mock.patch(
                "sys.stderr", new=io.StringIO()
            ):
                self.assertEqual(digests.main([str(bad)]), 1)


if __name__ == "__main__":
    unittest.main()

/* SPDX-License-Identifier: MPL-2.0
 * Copyright (C) 2026 M. Geisler (genkigenki/makkuro)
 *
 * Linker script of the Bluetooth controller image (core 1). The addresses come from the app's
 * interface (firmware/hal/x0x_ble_abi.h): flash XB_FLASH_XIP 0x02087000, 64 KiB; RAM
 * XB_RAM_LO..XB_RAM_HI 0x01C01800..0x01C07F00. The app checks them again before it starts the
 * image. */
CTL_HEAP_SIZE      = DEFINED(CTL_HEAP_SIZE)      ? CTL_HEAP_SIZE      : 0x2780;
CTL_ISR_STACK_SIZE = DEFINED(CTL_ISR_STACK_SIZE) ? CTL_ISR_STACK_SIZE : 0x800;
CTL_RUN_STACK_SIZE = DEFINED(CTL_RUN_STACK_SIZE) ? CTL_RUN_STACK_SIZE : 0x800;

MEMORY
{
    CFLASH (rx)  : ORIGIN = 0x02087000, LENGTH = 0x10000
    CRAM   (rwx) : ORIGIN = 0x01C01800, LENGTH = 0x6700
}

ENTRY(ctl_entry_init)

SECTIONS
{
    .ctl_header : { KEEP(*(.ctl_header)) } > CFLASH

    .text :
    {
        *(.text .text.*)
        *(.*_code)
        *(.*_code.*)
        . = ALIGN(4);
    } > CFLASH

    .rodata :
    {
        *(.rodata .rodata.*)
        *(.*_const)
        *(.LOG_TAG_CONST)
        . = ALIGN(4);
    } > CFLASH

    /* Code that must run with the flash off (RF trim, delays). */
    .ramtext :
    {
        __ctl_ram_lo = .;
        __ctl_ramtext_start = .;
        *(.ctl_ram_text)
        *(.volatile_ram_code)
        *(*.rf.text.cache.L2.rf_trim)
        . = ALIGN(4);
        __ctl_ramtext_end = .;
    } > CRAM AT > CFLASH
    __ctl_ramtext_lma = LOADADDR(.ramtext);

    .data :
    {
        __ctl_data_start = .;
        *(.data .data.*)
        *(.*_data)
        *(.volatile_ram)
        . = ALIGN(4);
        __ctl_data_end = .;
    } > CRAM AT > CFLASH
    __ctl_data_lma = LOADADDR(.data);
    __ctl_image_end = LOADADDR(.data) + SIZEOF(.data);

    .bss (NOLOAD) :
    {
        __ctl_bss_start = .;
        *(.bss .bss.*)
        *(.*_bss)
        *(.bd_base)
        *(COMMON)
        . = ALIGN(4);
        __ctl_bss_end = .;
    } > CRAM

    .heap (NOLOAD) :
    {
        . = ALIGN(8);
        __ctl_heap_start = .;
        . += CTL_HEAP_SIZE;
        __ctl_heap_end = .;
        . = ALIGN(8);
        __ctl_run_stack_lo = .;           /* init() and poll() */
        . += CTL_RUN_STACK_SIZE;
        __ctl_run_stack_hi = .;
        __ctl_isr_stack_lo = .;           /* core 1's interrupts (its ssp) */
        . += CTL_ISR_STACK_SIZE;
        __ctl_isr_stack_hi = .;
        __ctl_ram_hi = .;
    } > CRAM

    ASSERT(__ctl_image_end - 0x02087000 <= 0x10000, "the image is larger than the 64 KiB Bluetooth block")
    /DISCARD/ : { *(.comment) *(.note*) }
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* a76 (a74 owner test 1, PAD CLEAR FAIL): after Loopy goes away, no clip colour comes back
 * until Loopy is a listening host again (link up AND notify on). BEHAVIOR.md CLP-18.
 * The real BLE-MIDI host (src/ble/ble_midi_host.c), the real glue (src/ble/ble_glue.h) and the
 * real cell model (app/smk_apc40.h). service() has the order of ble.c ble_service: HCI frames,
 * then smk_apc_ble_link, then MIDI in (ble_usb_of_msg, smk_apc40_ble_colour_unheard) to the cells.
 *   cc -std=c99 -O2 -Wall -Ifirmware/src -Ifirmware/hal -Ifirmware/src/ble tests/smk_clip_ble_notify_test.c */
#include <stdio.h>
#include <string.h>
#include "x0x_ble_abi.h"
#include "ble_midi_host.c"
#include "ble_glue.h"
#include "app/smk_apc40.h"

static uint8_t vel[SMK_APC40_CLIP_COUNT], ch[SMK_APC40_CLIP_COUNT];
static uint8_t flags[SMK_APC40_CLIP_COUNT], tick[SMK_APC40_CLIP_COUNT];
static uint8_t link, now16;
static int fails;

static int fake_send(uint8_t t, const uint8_t *p, uint16_t n, void *ctx) { (void)t; (void)p; (void)n; (void)ctx; return 0; }
static void evt(bleh_t *h, const uint8_t *e, unsigned n) { bleh_rx(h, BLEH_H4_EVT, e, (uint16_t)n); }
static void cc(bleh_t *h, unsigned op)
{
    uint8_t e[9] = {0x0E, 4, 1, (uint8_t)op, (uint8_t)(op >> 8), 0, 0, 0, 0};
    if (op == 0x2002) { e[1] = 7; e[6] = 27; e[7] = 0; e[8] = 4; }
    evt(h, e, 2u + e[1]);
}
static void acl(bleh_t *h, const uint8_t *d, unsigned n)
{
    uint8_t b[64] = {0x40, 0x20, (uint8_t)(4 + n), 0, (uint8_t)n, 0, 4, 0};
    memcpy(b + 8, d, n);
    bleh_rx(h, BLEH_H4_ACL, b, (uint16_t)(8 + n));
}
static void cccd(bleh_t *h, uint8_t on) { uint8_t r[5] = {18, 7, 0, on, 0}; acl(h, r, 5); }
static void connect(bleh_t *h) { static const uint8_t c[21] = {0x3E, 19, 0x01, 0x00, 0x40, 0x00, 0x01}; evt(h, c, 21); }
static void disconnect(bleh_t *h) { static const uint8_t e[] = {0x05, 4, 0, 0x40, 0, 0x13}; evt(h, e, sizeof e); }
static void service(bleh_t *h)
{
    bleh_msg_t m;
    if (smk_apc40_link_lost(&link, (uint8_t)bleh_connected(h), (uint8_t)bleh_notifying(h)))
        smk_apc40_cells_clear(vel, ch, flags, tick);
    while (bleh_midi_next(h, &m)) {
        if (smk_apc40_ble_colour_unheard(ble_usb_of_msg(&m), (uint8_t)bleh_notifying(h)))
            continue;                       /* smk_apc_ble_event: no cell write, recorded as source 3 */
        if ((m.b[0] & 0xE0u) == 0x80u)
            smk_apc40_cell_event(vel, ch, flags, tick, m.b[1], m.b[0] & 0x0Fu,
                                 (m.b[0] & 0xF0u) == 0x80u ? 0u : m.b[2], now16);
    }
    (void)smk_apc40_cells_age(vel, ch, flags, tick, now16);   /* smk_apc_usb_tick: the 256 ms off-hold */
    now16++;
}
/* One Loopy feedback write (ATT Write Command 0x52 on the MIDI handle): note 0x20 violet, note 0x21 colour */
static void write_feedback(bleh_t *h)
{
    const uint8_t d[] = {0x80, 0x80, 0x90, 0x20, 0x45, 0x80, 0x90, 0x21, 0x50};
    uint8_t b[40] = {0x52, 6, 0};
    memcpy(b + 3, d, sizeof d);
    acl(h, b, 3 + sizeof d);
}
static unsigned lit(void)
{
    unsigned n, k = 0;
    for (n = 0; n < SMK_APC40_CLIP_COUNT; n++)
        k += vel[n] != 0u || flags[n] != 0u;
    return k;
}
static void check(int ok, const char *what)
{
    printf("%s %s (lit %u)\n", ok ? "PASS" : "FAIL", what, lit());
    fails += !ok;
}
static void up(bleh_t *h)   /* Loopy connected and listening, pads show its colours */
{
    connect(h); service(h); cccd(h, 1); service(h);
    write_feedback(h); service(h);
}

int main(void)
{
    static bleh_t h;
    static const uint8_t addr[6] = {1, 2, 3, 4, 5, 6};
    static const unsigned ops[] = {0x0C03, 0x0C01, 0x2001, 0x2002, 0x2005, 0x2006, 0x2008, 0x2009};
    unsigned i;
    bleh_init(&h, fake_send, 0, "X0X-TEST", addr);
    bleh_start(&h);
    for (i = 0; i < 8u; i++)
        cc(&h, ops[i]);
    service(&h);

    /* A. Loopy closes its input from X0X: the central writes CCCD 0, the link stays up.
     *    Loopy still sends feedback to the APC40 output (refresh, blink flash, state change). */
    up(&h);
    check(lit() == 2u, "A0 Loopy colours on the pads");
    cccd(&h, 0); service(&h);
    check(lit() == 0u, "A1 CCCD 0 clears the pads");
    write_feedback(&h); service(&h);
    check(lit() == 0u, "A2 after CCCD 0 a Loopy feedback write does not light the pads again");
    for (i = 0; i < 100u; i++) service(&h);
    check(lit() == 0u, "A3 the pads stay dark while notify stays off");

    /* B. CCCD 0 and a feedback write in the same event poll (8 frames per ble_service). */
    cccd(&h, 1); service(&h); write_feedback(&h); service(&h);
    cccd(&h, 0); write_feedback(&h); service(&h);
    check(lit() == 0u, "B  CCCD 0 and feedback in one poll: the pads stay dark");

    /* C. The link ends, iOS connects again at once (known iOS behaviour after a link loss),
     *    and a write comes before the CCCD write. */
    cccd(&h, 1); service(&h); write_feedback(&h); service(&h);
    disconnect(&h); service(&h);
    check(lit() == 0u, "C1 disconnect clears the pads");
    connect(&h); service(&h); write_feedback(&h); service(&h);
    check(lit() == 0u, "C2 reconnect without notify: a feedback write does not light the pads");

    /* D. No regression: Loopy listens again and sends feedback: the colours show. */
    cccd(&h, 1); service(&h); write_feedback(&h); service(&h);
    check(lit() == 2u, "D  notify on again with new feedback shows the colours");
    for (i = 0; i < 100u; i++) service(&h);
    check(lit() == 2u, "E  a steady link keeps the colours");

    printf("%s %d fail\n", fails ? "FAIL" : "PASS", fails);
    return fails ? 1 : 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* One packed copy of the twelve pitch-class names (C … B), plus one pointer
 * table into that pack. The UI note labels, clip-mode ROOT, and chord spelling
 * all read these — keep a single copy in each translation unit.
 * Include once per translation unit. */
#pragma once

static const char X0X_NOTE_PACK[] = "C\0C#\0D\0D#\0E\0F\0F#\0G\0G#\0A\0A#\0B";

_Static_assert(sizeof X0X_NOTE_PACK == 29, "note pack size");

/* Pointers into X0X_NOTE_PACK (same offsets as the old per-literal NOTE_N). */
static const char *const X0X_NOTE_N[12] = {
    X0X_NOTE_PACK + 0,  X0X_NOTE_PACK + 2,  X0X_NOTE_PACK + 5,  X0X_NOTE_PACK + 7,
    X0X_NOTE_PACK + 10, X0X_NOTE_PACK + 12, X0X_NOTE_PACK + 14, X0X_NOTE_PACK + 17,
    X0X_NOTE_PACK + 19, X0X_NOTE_PACK + 22, X0X_NOTE_PACK + 24, X0X_NOTE_PACK + 27
};

/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X sequencer; see sequencer.h for the model. */
#include "sequencer.h"
#include "tb3po.h"
#include "../x0x_cold.h"              /* X0X_COLD: boot/UI cue/chain — not advance/fire/clock/MIDI */

#define NEVER 0xFFFFFFFFu
#define RANDOM_PASS_STEPS 0x7Fu
#define RANDOM_SWING_ODD  0x80u
#define BASS_SLIDE_OVERLAP_Q8 (FS / 50u * 256u) /* 20 ms after the next note-on */

static const uint8_t TICKS_PER_STEP[NRATES] = {6, 4, 3, 8};     /* 24 ppqn: 1/16, 1/16T, 1/32, 1/8T */
/* One GM note map for seq MIDI out and engine MIDI in (was a second copy in engine.c). */
const uint8_t GM_DRUM[NKIT][NDRUM] = {
    {36, 38, 41, 45, 50, 37, 39, 42, 46, 49, 51},   /* 909: BD SD LT MT HT RS CP CH OH CR RD */
    {36, 38, 41, 45, 50, 37, 39, 56, 49, 46, 42},   /* 808: BD SD LT MT HT RS CP CB CY OH CH */
};
/* Default MIDI channels (0-based): 909 10, 808 11, 303s 2/3, break 4 — also project_apply_io. */
const uint8_t SEQ_CH_DEFAULT[NTRACKS] = {9, 10, 1, 2, 3};

X0X_COLD void seq_init(seq_t *s, pattern_t *patterns)
{
    uint32_t i;
    uint8_t *p = (uint8_t *)s;
    for (i = 0; i < sizeof *s; i++)
        p[i] = 0;
    s->pat = patterns;
    for (i = 0; i < NTRACKS; i++)
        s->pcue[i] = 0xFF;
    s->bpm = 125.0f;
    s->ext_bpm = 125.0f;
    s->accent_q7 = 88;                /* a 909 non-accented hit sits ~3 dB under an accent */
    s->send_clock = 1;
    for (i = 0; i < NTRACKS; i++)
        s->ch[i] = SEQ_CH_DEFAULT[i];
    for (i = 0; i < NTRACKS; i++) {
        s->t[i].to_next = NEVER;
        s->t[i].pp_dir = 1;
        s->t[i].rng = 0x1234567u * (i + 1);
    }
    s->clk_to_next = NEVER;
}

float seq_tempo(const seq_t *s) { return s->ext ? s->ext_bpm : s->bpm; }

uint32_t seq_step_q8(const seq_t *s, int rate)
{
    float bpm = seq_tempo(s), q;
    if (bpm < 20.0f)
        bpm = 20.0f;
    if (bpm > 300.0f)
        bpm = 300.0f;
    q = (float)FS * 60.0f / bpm;                    /* samples per quarter */
    return (uint32_t)(q * 256.0f * (float)TICKS_PER_STEP[rate & 3] / 24.0f);
}

__attribute__((noinline)) static const dpart_t *dpart(const seq_t *s, int k) { return &s->pat[s->ppat[k]].drum[k]; }
static int is_drum(int t) { return t < NKIT; }
static int is_bass(int t) { return t >= TRK_BASS0 && t < TRK_BASS0 + NBASS; }
__attribute__((noinline)) static bpart_t *bpart(const seq_t *s, int b) { return &s->pat[s->ppat[TRK_BASS0 + b]].bass[b]; }

int seq_part_len(const seq_t *s, int t)
{
    int n = is_drum(t) ? dpart(s, t)->len : t == TRK_BRK ? 16 : bpart(s, t - TRK_BASS0)->len;
    return n < 1 ? 1 : n > NSTEPS ? NSTEPS : n;
}

/* noinline: rate lookup shared by swing/advance/fire (else -O2 triples the ternary). */
__attribute__((noinline)) static int part_rate(const seq_t *s, int t)
{
    return (is_drum(t) ? dpart(s, t)->rate : t == TRK_BRK ? RATE_16 : bpart(s, t - TRK_BASS0)->rate) & 3;
}

/* swing offset of a step, Q8: odd 16ths / 32nds come late; triplets are never swung.
 * noinline: one body for step timing paths (else -O2 inlines the groove math). */
__attribute__((noinline)) static uint32_t swing_q8(const seq_t *s, int rate, uint32_t step_q8)
{
    uint32_t sw = s->pat[s->ppat[TRK_DRUM]].swing;   /* the 909 is the bar: its pattern's groove */
    if (rate == RATE_16T || rate == RATE_8T || !sw)
        return 0;
    if (sw > 100u)
        sw = 100u;
    return step_q8 / 200u * sw;                     /* 100 -> half a step late = 75 % (32-bit: no __udivdi3) */
}

__attribute__((noinline)) static uint32_t rng_next(uint32_t *r)
{
    uint32_t x = *r ? *r : 1;
    x ^= x << 13;
    x ^= x >> 17;
    x ^= x << 5;
    return *r = x;
}

/* the step after p in this part's direction (also used to look ahead for TIEs) */
static int next_pos(seq_t *s, int t, int p, int commit)
{
    seq_track_t *tr = &s->t[t];
    int len = seq_part_len(s, t), dir = is_bass(t) ? bpart(s, t - TRK_BASS0)->dir : DIR_FWD, n;
    switch (dir & 3) {
    case DIR_REV:
        return (p - 1 + len) % len;
    case DIR_PINGPONG:
        if (len == 1)
            return 0;
        /* A live length edit can put the old playhead beyond the new range.
         * Return directly to its last step, then play backwards; never walk
         * through the disabled steps outside the newly selected length. */
        if (p < 0 || p >= len) {
            if (commit)
                tr->pp_dir = (int8_t)(p < 0 ? 1 : -1);
            return p < 0 ? 0 : len - 1;
        }
        n = p + tr->pp_dir;
        if (n >= len || n < 0) {
            n = p - tr->pp_dir;
            if (commit)
                tr->pp_dir = (int8_t)-tr->pp_dir;
        }
        return n;
    case DIR_RANDOM:
        if (!commit)
            return (p + 1) % len;                    /* a TIE look-ahead cannot know: assume forward */
        return (int)(rng_next(&tr->rng) % (uint32_t)len);
    default:
        return (p + 1) % len;
    }
}

__attribute__((noinline)) static void midi(const seq_sink_t *o, uint8_t st, uint8_t d1, uint8_t d2)
{
    if (o->midi)
        o->midi(o->ctx, st, d1, d2);
}

/* Note Off — shared by flush / drum hit / fire_bass / slide expiry (one body on pi32). */
__attribute__((noinline)) static void midi_note_off(const seq_sink_t *o, uint8_t ch, uint8_t note)
{
    midi(o, (uint8_t)(0x80 | ch), note, 0);
}

/* End the overlapping slide Note Off (flush / new onset / slide timer). */
__attribute__((noinline)) static void bass_slide_midi_off(seq_t *s, int b, const seq_sink_t *o)
{
    if (s->bass_slide_valid[b])
        midi_note_off(o, s->bass_slide_ch[b], s->bass_slide_old[b]);
    s->bass_slide_valid[b] = 0;
    s->bass_slide_off[b] = 0;
}

/* noinline: flush glue for seq_midi_flush / release / fire / channel edit. */
__attribute__((noinline)) static void bass_midi_flush(seq_t *s, int b, const seq_sink_t *o)
{
    bass_slide_midi_off(s, b, o);
    if (s->bass_out_valid[b])
        midi_note_off(o, s->bass_out_ch[b], s->bass_notes_out[b]);
    s->bass_out_valid[b] = 0;
}

void seq_midi_flush(seq_t *s, const seq_sink_t *o)
{
    for (int b = 0; b < NBASS; b++)
        bass_midi_flush(s, b, o);
}

__attribute__((noinline)) static void bass_release(seq_t *s, int b, const seq_sink_t *o)
{
    seq_track_t *tr = &s->t[TRK_BASS0 + b];
    bass_midi_flush(s, b, o);
    if (tr->sounding) {
        o->bass_off(o->ctx, b);
        tr->sounding = 0;
    }
    tr->held_note = 0;
    tr->to_off = 0;
}


__attribute__((noinline)) static void drum_midi_hit(seq_t *s, const seq_sink_t *o, int k, int v, uint8_t mv)
{
    if (s->send_notes && s->ch[k] != SEQ_CH_OFF) {
        midi(o, (uint8_t)(0x90 | s->ch[k]), GM_DRUM[k][v], mv);
        midi_note_off(o, s->ch[k], GM_DRUM[k][v]);
    }
}

__attribute__((noinline)) static void fire_drum(seq_t *s, int k, int p, uint32_t skip, const seq_sink_t *o)
{
    const dpart_t *d = dpart(s, k);
    uint32_t bit = 1u << (p & 31);
    int w = p >> 5;
    float accent_vel = (d->accent[w] & bit) ? 1.0f : (float)s->accent_q7 / 127.0f;
    int v;
    for (v = 0; v < NDRUM; v++) {
        uint8_t sv;
        float vel;
        uint8_t mv;
        if (!(d->hit[v][w] & bit) || ((s->mute | s->vmute) & (1u << (k * NDRUM + v))))
            continue;
        /* A T_VEL lane (written by black-key REC) wins; else the shared accent row / accent_q7. */
        sv = s->drum_vel[k][v];
        if (sv) {
            if (sv > 127u)
                sv = 127u;
            vel = (float)sv / 127.0f;
            mv = sv;
        } else {
            vel = accent_vel;
            mv = (uint8_t)(vel * 127.0f);
        }
        if (skip >> v & 1u) {                        /* recorded live on this pass: the key sounded it */
            drum_midi_hit(s, o, k, v, mv);
            continue;
        }
        if (!o->drum(o->ctx, k, v, vel))
            continue;                                /* its chance said no: no MIDI either */
        drum_midi_hit(s, o, k, v, mv);
    }
}

static uint32_t bass_slot_q8(const seq_t *s, int b, int p)
{
    int t = TRK_BASS0 + b;
    uint32_t L = seq_step_q8(s, bpart(s, b)->rate);
    uint32_t sw = swing_q8(s, bpart(s, b)->rate, L);
    if (bpart(s, b)->dir == DIR_RANDOM)
        return (s->t[t].mut_steps & RANDOM_SWING_ODD) ? L + sw : L - sw;
    int np = next_pos((seq_t *)s, t, p, 0);
    return !(np & 1) && !(p & 1) ? L : (np & 1) ? L + sw : L - sw;
}

__attribute__((noinline)) static void fire_bass(seq_t *s, int b, int p, uint32_t step_q8, uint32_t carry, uint32_t skip, const seq_sink_t *o)
{
    seq_track_t *tr = &s->t[TRK_BASS0 + b];
    bpart_t *bp = bpart(s, b);
    const bstep_t *st = &bp->step[p];
    int gate = bstep_gate(st), note, hold, nx;
    seq_bass_rec_t *r = &s->rec_bass[b];
    if (r->active && r->pat != s->ppat[TRK_BASS0 + b])
        seq_rec_cancel(s, b);
    if (r->active) {
        if (r->entered == 2 || (r->entered && p == r->first)) {
            r->entered = 2; /* periodic pattern cannot encode an extra loop count */
            tr->to_off = 0;
            return;
        }
        if (p == r->first && !r->entered) { r->entered = 1; r->at = s->ext_now; r->slot = bass_slot_q8(s, b, p); }
        else if (r->entered) {
            /* Across the loop, keep the onset but suppress its live retrigger. */
            bp->step[r->last].flags &= 15u; /* continuation, not an endpoint */
            if (p != r->first) {
                bp->step[p].note = r->note;
                bp->step[p].velocity = bp->step[r->first].velocity;
                bp->step[p].flags = G_TIE | 0xF0u;
#if X0X_BASS_NOTE_SOUND
                seq_bass_sound_clear(s,b,s->ppat[TRK_BASS0+b],p);
#endif
            }
            r->prev = r->last;
            r->last = (uint8_t)p;
            r->slot = bass_slot_q8(s, b, p);
            r->at = s->ext_now;
        }
        if (!r->entered) { tr->to_off = 0; return; }
        skip = 1; /* live input owns audio; reuse real MIDI echo/gate bookkeeping */
        gate = bstep_gate(st);
    }
    uint8_t prev_slide = tr->held_note & 0x80u;     /* bit 7: the step that sounded slides on */
    if (s->mute & (1u << (MUTE_BASS0 + b)))
        gate = G_REST;
    /* A TIE continues an audible note; an orphan TIE is a rest, never an onset. */
    if (gate == G_REST || (gate == G_TIE && !tr->sounding)) {
        bass_release(s, b, o);
        tr->held_note = 0;
        return;
    }
    note = st->note + (int)bp->transpose - 24;
    note = note < 0 ? 0 : note > 127 ? 127 : note;
    if (gate == G_NOTE || !tr->sounding) {
        int slide = tr->sounding && prev_slide;
        /* A chance-rejected step is a rest for both the internal 303 and MIDI out.
         * REC's live-hit skip still echoes MIDI (REC-06); it is not a chance miss. */
        int played = skip || o->bass_on(o->ctx, b, note, (st->flags & BS_ACCENT) != 0, slide, bstep_velocity(st));
        if (played && s->send_notes && s->ch[TRK_BASS0 + b] != SEQ_CH_OFF) {
            uint8_t old = s->bass_notes_out[b], ch = s->ch[TRK_BASS0 + b];
            uint8_t had_old = s->bass_out_valid[b], old_ch = s->bass_out_ch[b];
            if (s->bass_slide_valid[b])                  /* only one old MIDI pitch can remain open */
                bass_slide_midi_off(s, b, o);
            /* A repeated pitch must end before its new Note On: otherwise its old
             * Note Off could silence the new voice on a monophonic receiver. */
            if (had_old && (old == note || old_ch != ch))
                midi_note_off(o, old_ch, old);
            midi(o, (uint8_t)(0x90 | ch), (uint8_t)note, bstep_velocity(st));
            if (had_old && old != note && old_ch == ch) {
                if (slide) {
                    s->bass_slide_old[b] = old;
                    s->bass_slide_ch[b] = old_ch;
                    s->bass_slide_valid[b] = 1;
                    s->bass_slide_off[b] = BASS_SLIDE_OVERLAP_Q8;
                } else
                    midi_note_off(o, old_ch, old);
            }
            s->bass_notes_out[b] = (uint8_t)note;
            s->bass_out_ch[b] = ch;
            s->bass_out_valid[b] = 1;
        } else if (s->bass_out_valid[b] || s->bass_slide_valid[b]) {
            /* Output was disabled or its channel set OFF while a note sounded. */
            bass_midi_flush(s, b, o);
        }
        if (!played) {                                  /* rejected chance: a real rest, not a held 303 */
            tr->sounding = 0;
            tr->held_note = 0;
            tr->to_off = 0;
            return;
        }
        tr->sounding = 1;
    }
    nx = next_pos(s, TRK_BASS0 + b, p, 0);
    if ((bp->dir & 3) == DIR_RANDOM) {
        /* Preview the next random step without advancing the committed RNG.
         * A random TIE must hold the note picked before it, not the forward
         * neighbour (which may never play on this pass). */
        uint32_t peek_rng = tr->rng;
        nx = (int)(rng_next(&peek_rng) % (uint32_t)seq_part_len(s, TRK_BASS0 + b));
    }
    hold = (st->flags & BS_SLIDE) || bstep_gate(&bp->step[nx]) == G_TIE;
    tr->held_note = (uint8_t)((note & 0x7F) | ((st->flags & BS_SLIDE) ? 0x80 : 0));
    unsigned end = st->flags >> BS_END_SHIFT;
    tr->to_off = r->active ? 0 : end ? carry + (bass_slot_q8(s, b, p) / 15u) * end : hold ? 0 : carry + step_q8 / 2u;
}

int seq_part_muted(const seq_t *s, int p)
{
    uint32_t m = seq_part_mask(p);
    return (s->mute & m) == m;
}

/* the song's bar k into the parts and their mutes (into next[]: the caller switches) */
static void song_read(seq_t *s, int k, uint8_t *next)
{
    const song_bar_t *b = &s->song->bar[k];
    uint32_t mute = 0;                                  /* the bar decides every part's mute (built up, */
    int p;                                              /* not masked: ~mask reads as a ROM address) */
    for (p = 0; p < NTRACKS; p++) {
        next[p] = b->pat[p] < NPAT ? b->pat[p] : 0;
        if (b->mute >> p & 1u)
            mute |= seq_part_mask(p);
    }
    s->mute = mute;
}

/* the live state (next[], the mutes) into the song's bar k, growing it */
static void song_write(seq_t *s, int k, const uint8_t *next)
{
    song_bar_t *b = &s->song->bar[k];
    int p;
    b->mute = 0;
    for (p = 0; p < NTRACKS; p++) {
        b->pat[p] = next[p];
        if (seq_part_muted(s, p))
            b->mute |= (uint8_t)(1u << p);
    }
    if (s->song->len < k + 1)
        s->song->len = (uint16_t)(k + 1);
}

static int song_plays(const seq_t *s) { return s->song_on && s->song && (s->song_rec || s->song->len); }

/* the bar's end (the 909 wrapping), or the start: cues, the chain or the song decide each
 * part's next pattern. Returns the parts whose pattern changed (bit t). */
static uint32_t bar_end(seq_t *s, int start)
{
    uint8_t next[NTRACKS];
    uint32_t changed = 0;
    int t, cued = 0;
    for (t = 0; t < NTRACKS; t++)
        next[t] = s->ppat[t];
    if (song_plays(s) && !s->song_rec) {               /* the song: its next bar (looping), or this one again */
        int k = start ? s->song_start : s->song_pos + 1;
        if (!start && s->song_rep > 1 && s->song_pos < s->song->len) {
            k = s->song_pos;
            s->song_rep--;
        } else {
            if (k >= s->song->len)
                k = 0;
            s->song_rep = (uint8_t)SONG_REP(&s->song->bar[k]);
        }
        s->song_pos = (uint16_t)k;
        song_read(s, k, next);
        for (t = 0; t < NTRACKS; t++)
            s->pcue[t] = 0xFF;
    } else {
        for (t = 0; t < NTRACKS; t++)
            if (s->pcue[t] < NPAT) {
                next[t] = s->pcue[t];
                s->pcue[t] = 0xFF;
                cued = 1;
            }
        if (!cued && !start && s->chain_a != s->chain_b) {
            int a = s->chain_a < s->chain_b ? s->chain_a : s->chain_b;
            int b = s->chain_a < s->chain_b ? s->chain_b : s->chain_a, c = s->ppat[TRK_DRUM];
            c = (c < a || c >= b) ? a : c + 1;
            for (t = 0; t < NTRACKS; t++)
                next[t] = (uint8_t)c;
        }
        if (song_plays(s)) {                           /* recording: what plays is the song */
            int k = start ? s->song_start : s->song_pos + 1;
            if (k >= NSONG) {
                s->song_rec = 0;                       /* full */
            } else {
                if (start && k < s->song->len)         /* overdub from where the song is */
                    song_read(s, k, next);
                s->song_pos = (uint16_t)k;
                song_write(s, k, next);
            }
        }
    }
    for (t = 0; t < NTRACKS; t++)
        if (next[t] != s->ppat[t]) {
            s->ppat[t] = next[t];
            changed |= 1u << t;
        }
    return changed;
}

__attribute__((noinline)) static void auto_mutate(seq_t *s, int b)
{
    bpart_t *bp = bpart(s, b);
    seq_track_t *tr = &s->t[TRK_BASS0 + b];
    tr->bars++;
    if (bp->gen.mutate_bars && tr->bars % bp->gen.mutate_bars == 0)
        tb3po_mutate(bp, &s->mut_rng[b]);
}

/* fire track t's next step now; returns the parts whose pattern changed (the 909 wrapping) */
static uint32_t fire_step(seq_t *s, int t, const seq_sink_t *o)
{
    seq_track_t *tr = &s->t[t];
    int rate = part_rate(s, t), p, wrapped;
    uint32_t changed = 0, skip;
    uint32_t L = seq_step_q8(s, rate);
    uint32_t carry = tr->to_next < 256u ? tr->to_next : 0;   /* the step was due this far into the sample: keep it */
    int bass = is_bass(t);
    if (!tr->started) {
        p = (bass && bpart(s, t - TRK_BASS0)->dir == DIR_REV) ? seq_part_len(s, t) - 1 : 0;
        tr->started = 1;
        wrapped = 0;
    } else {
        p = next_pos(s, t, tr->pos, 1);
        /* The reverse pass wraps only at its last step, not also at zero.
         * Random steps have no positional wrap: count a logical pass below. */
        wrapped = !bass ? p == 0 :
            (bpart(s, t - TRK_BASS0)->dir == DIR_REV ? p == seq_part_len(s, t) - 1 :
             bpart(s, t - TRK_BASS0)->dir != DIR_RANDOM && p == 0);
    }
    if (wrapped && t == TRK_DRUM && (changed = bar_end(s, 0)) != 0) {
        rate = part_rate(s, t);                       /* the 909's new pattern */
        L = seq_step_q8(s, rate);
        p = 0;
    }
    if (bass) {
        if (bpart(s, t - TRK_BASS0)->dir == DIR_RANDOM) {
            /* Visiting step zero at random is not a bar boundary. Count
             * LEN actual played steps for both TB-3PO and probability. */
            uint8_t count = (uint8_t)(tr->mut_steps & RANDOM_PASS_STEPS);
            if (count >= seq_part_len(s, t)) {
                count = 0;
                auto_mutate(s, t - TRK_BASS0);
            }
            /* A random pick is a note choice, not a timing slot. Preserve the
             * alternating swing slot across odd-length passes and live edits. */
            tr->mut_steps = (uint8_t)(((tr->mut_steps ^ RANDOM_SWING_ODD) & RANDOM_SWING_ODD) | (count + 1u));
        } else {
            tr->mut_steps = 0;
            if (wrapped)
                auto_mutate(s, t - TRK_BASS0);
        }
    }
    if (wrapped && (t == TRK_BRK || is_drum(t)))   /* (the 303s count theirs in auto_mutate) */
        tr->bars++;
    if (changed & 1u)                                /* the 909's new pattern: its passes from 1 again, as */
        tr->bars = 0;                                /* restart() does for the others (probability cycles) */
    skip = (tr->rec_skip && tr->rec_skip_step == p && tr->rec_skip_pat == s->ppat[t]) ? tr->rec_skip : 0u;
    tr->rec_skip = 0;                                /* one pass only */
    tr->pos = (uint8_t)p;
    if (o->step)                                     /* first: the step's motion and p-locks, which the hit */
        o->step(o->ctx, t, p);                       /* below must hear (a drum takes its tune as it fires) */
    if (is_drum(t))
        fire_drum(s, t, p, skip, o);
    else if (t == TRK_BRK) {
        if (o->brk)
            o->brk(o->ctx, p, tr->bars, (float)L / 256.0f,
                   (s->pat[s->ppat[TRK_BRK]].brk.steps >> p & 1u) && !(s->mute & (1u << MUTE_BRK)));
    } else
        fire_bass(s, t - TRK_BASS0, p, L, carry, skip, o);
    if (s->ext) {
        tr->to_next = tr->ext_due ? 0 : NEVER;       /* the clock arms the next one (a burst: at once) */
        if (tr->ext_due)
            tr->ext_due--;
    } else {
        /* the step that follows p: swung if it is an odd one */
        int np = next_pos(s, t, p, 0);
        uint32_t sw = swing_q8(s, rate, L);
        if (bass && bpart(s, t - TRK_BASS0)->dir == DIR_RANDOM) {
            /* Swing belongs to successive musical time slots, not to the
             * parity of the randomly selected source-step position. */
            tr->to_next = carry + ((tr->mut_steps & RANDOM_SWING_ODD) ? L + sw : L - sw);
        } else {
            tr->to_next = carry + ((np & 1) ? L + sw : L - sw);
            if (!(np & 1) && (p & 1) == 0)           /* even -> even (odd lengths, wraps): no swing */
                tr->to_next = carry + L;
        }
    }
    return changed;
}

/* Shared by Start/Continue and pattern-switch restart: step timers (+ optional from-top fields).
 * clear_to_off: Start/Continue zero note-off timers; restart leaves them (voice already released). */
__attribute__((noinline)) static void track_arm(seq_t *s, int t, int from_top, int clear_to_off)
{
    seq_track_t *tr = &s->t[t];
    if (from_top) {
        tr->started = 0;
        tr->bars = 0;
        tr->pp_dir = 1;
        tr->mut_steps = 0;
    }
    if (clear_to_off)
        tr->to_off = 0;
    tr->ext_due = 0;
    tr->rec_skip = 0;
    tr->to_next = s->ext ? NEVER : 0;
    tr->ext_ticks = (uint8_t)(TICKS_PER_STEP[part_rate(s, t)] - 1);   /* the first clock is the downbeat */
}

__attribute__((noinline)) static void restart(seq_t *s, uint32_t parts)  /* parts whose pattern switched: from step 1 (not the 909's) */
{
    int t;
    for (t = 1; t < NTRACKS; t++) {
        if (!(parts >> t & 1u))
            continue;
        track_arm(s, t, 1, 0);
    }
}

__attribute__((noinline)) static void bass_release_all(seq_t *s, const seq_sink_t *o)
{
    int b;
    for (b = 0; b < NBASS; b++)
        bass_release(s, b, o);
}

__attribute__((noinline)) static void bass_and_brk_stop(seq_t *s, const seq_sink_t *o)
{
    bass_release_all(s, o);
    if (o->brk_stop)
        o->brk_stop(o->ctx);
}

__attribute__((noinline)) static void seq_send_rt(seq_t *s, const seq_sink_t *o, uint8_t remote, uint8_t st)
{
    if (!s->ext && s->send_clock && (!s->midi_req || !remote))
        midi(o, st, 0, 0);
}

__attribute__((noinline)) static void do_start(seq_t *s, int from_top, const seq_sink_t *o, uint8_t remote)
{
    int t;
    bass_release_all(s, o);                /* Start/Continue reinitialises timers: release old notes first */
    if (from_top)
        bar_end(s, 1);                                /* cues, or the song's start bar */
    for (t = 0; t < NTRACKS; t++)
        track_arm(s, t, from_top, 1);
    if (from_top || !s->metro_period) {
        s->metro_phase = s->metro_period = 0;
        s->metro_tick = 24; /* waiting: next accepted clock is phase zero */
    } /* Continue preserves musical position and the stopped visual phase. */
    s->clk_to_next = 0;
    s->playing = 1;
    seq_send_rt(s, o, remote, from_top ? 0xFA : 0xFB);
}

__attribute__((noinline)) static void do_stop(seq_t *s, const seq_sink_t *o, uint8_t remote)
{
    int t;
    s->playing = 0;
    bass_and_brk_stop(s, o);
    for (t = 0; t < NTRACKS; t++) {
        s->t[t].to_next = NEVER;
        s->t[t].ext_due = 0;
        s->t[t].rec_skip = 0;
    }
    seq_send_rt(s, o, remote, 0xFC);
}

__attribute__((noinline)) static void ext_set_period(seq_t *s, uint32_t q)   /* samples per external clock, Q8 */
{
    s->ext_period = q;
    s->ext_bpm = (float)FS * 60.0f * 256.0f / (24.0f * (float)q);
}

/* external clock ticks: the tempo, and arm the steps they complete. Bluetooth MIDI gives all the ticks
 * of one connection event (7.5-30 ms) in one block. Thus the time between two blocks is not one tick
 * period. The tempo is the mean tick period over the last beats in the ring (SEQ_EXT_BEATS). */
static void ext_ticks(seq_t *s)
{
    int t;
    uint32_t n = s->ext_pending, k = n;
    s->ext_pending = 0;
    if (s->ext_skip || (!s->ext_nb && !s->ext_q)) {   /* first tick after any beat-ring reset is no period */
        s->ext_skip = 0;
        s->ext_since = FS;
    }
    for (; n; n--) {
        if (s->ext_since > 0 && s->ext_since < FS && s->ext_nb < 2u) {   /* the first beats: smoothed */
            uint32_t q = (s->ext_since << 8) / k;     /* the ticks of one block share its time */
            ext_set_period(s, s->ext_period ? s->ext_period - (s->ext_period >> 3) + (q >> 3) : q);
        }
        s->ext_since = 0;
        if (++s->ext_q >= 24u) {                      /* a beat: the mean since the oldest beat in the ring */
            s->ext_q = 0;
            if (s->ext_nb) {
                uint32_t d = s->ext_now - s->ext_beat[s->ext_nb < SEQ_EXT_BEATS ? 0u : s->ext_bi], m = 24u * s->ext_nb;
                uint32_t w = ((d / m) << 8) + ((d % m) << 8) / m, p = s->ext_period;
                if (s->ext_nb >= 2u && (w > p ? w - p : p - w) < (p >> 6))   /* a change under 1/64: smoothed */
                    w = p - (p >> 2) + (w >> 2);
                if (w)                                /* (0: all the ticks of the ring in one block) */
                    ext_set_period(s, w);
            }
            s->ext_beat[s->ext_bi] = s->ext_now;
            s->ext_bi = (uint8_t)((s->ext_bi + 1u) % SEQ_EXT_BEATS);
            if (s->ext_nb < SEQ_EXT_BEATS)
                s->ext_nb++;
        }
        if (!s->playing)
            continue;
        s->metro_tick = s->metro_tick >= 23u ? 0 : (uint8_t)(s->metro_tick + 1u);
        for (t = 0; t < NTRACKS; t++) {
            seq_track_t *tr = &s->t[t];
            int rate = part_rate(s, t), tps = TICKS_PER_STEP[rate];
            if (++tr->ext_ticks < tps)
                continue;
            tr->ext_ticks = 0;
            if (tr->to_next != NEVER) {               /* the last one not played yet (one block): it too */
                if (tr->ext_due < 255u)
                    tr->ext_due++;
                continue;
            }
            {
                int np = tr->started ? next_pos(s, t, tr->pos, 0) : 0;
                int odd = is_bass(t) && bpart(s, t - TRK_BASS0)->dir == DIR_RANDOM
                    ? (tr->mut_steps & RANDOM_SWING_ODD) != 0 : (np & 1) != 0;
                uint32_t L = s->ext_period ? s->ext_period * (uint32_t)tps : seq_step_q8(s, rate);
                tr->to_next = odd ? swing_q8(s, rate, L) : 0;
            }
        }
    }
}

uint32_t seq_until_event(seq_t *s, uint32_t n)
{
    uint32_t m = n, e;
    int t;
    if (!s->playing)
        return n;
    for (t = 0; t < NTRACKS; t++) {
        if (s->t[t].to_next != NEVER && (e = s->t[t].to_next >> 8) < m)
            m = e;
        if (s->t[t].to_off && (e = s->t[t].to_off >> 8) < m)
            m = e;
    }
    for (t = 0; t < NBASS; t++)
        if (s->bass_slide_off[t] && (e = s->bass_slide_off[t] >> 8) < m)
            m = e;
    if (!s->ext && s->send_clock && (e = s->clk_to_next >> 8) < m)
        m = e;
    return m ? m : 1;
}

/* the external clock is gone: a new beat ring, and the internal tempo takes the last measured one */
__attribute__((noinline)) static void clock_lost(seq_t *s)
{
    s->ext_nb = s->ext_bi = s->ext_q = 0;             /* the next clock: a new beat ring */
    if (s->ext_period) {                              /* the internal tempo takes the last measured one */
        float b = (float)(int)(s->ext_bpm + 0.5f);   /* whole BPM, as the TEMPO knob sets it */
        s->bpm = b < 20.0f ? 20.0f : b > 275.0f ? 275.0f : b;
    }
}

static void to_internal(seq_t *s)
{
    int t;
    s->ext = 0;
    clock_lost(s);
    for (t = 0; t < NTRACKS; t++)
        if (s->playing && s->t[t].to_next == NEVER)
            s->t[t].to_next = 0;
}

/* CLOCK SOURCE set to INTERNAL while X0X follows a clock: each part's next step comes when the clock
 * would give it, so no step comes early or late (a clock that is gone: at once, as to_internal) */
__attribute__((noinline)) static void switch_internal(seq_t *s)
{
    int t;
    uint32_t per = s->ext_period ? s->ext_period : seq_step_q8(s, RATE_16) / 6u;   /* one tick, Q8 */
    uint32_t since = s->ext_since < (1u << 23) ? s->ext_since << 8 : NEVER;
    for (t = 0; t < NTRACKS && s->playing; t++) {
        seq_track_t *tr = &s->t[t];
        int rate = part_rate(s, t), tps = TICKS_PER_STEP[rate];
        uint32_t left;
        if (tr->to_next != NEVER)
            continue;
        left = (tr->ext_ticks == 0xFFu ? 1u : (uint32_t)(tps - tr->ext_ticks)) * per;   /* to the next step */
        /* CLOCK SOURCE handoff uses the same next musical time slot as
         * external clock scheduling. RANDOM note index is not timing parity. */
        int odd = is_bass(t) && bpart(s, t - TRK_BASS0)->dir == DIR_RANDOM
            ? (tr->mut_steps & RANDOM_SWING_ODD) != 0
            : ((tr->started ? next_pos(s, t, tr->pos, 0) : 0) & 1) != 0;
        if (odd)
            left += swing_q8(s, rate, per * (uint32_t)tps);
        tr->to_next = left > since ? left - since : 0;
    }
    s->ext = 0;
    clock_lost(s);
}

__attribute__((noinline)) static void rephase(seq_t *s)                         /* the next tick is tick 0 of the step that plays */
{
    int t;
    s->metro_tick = 24;
    for (t = 0; t < NTRACKS; t++) {
        s->t[t].to_next = NEVER;
        s->t[t].ext_due = 0;
        s->t[t].ext_ticks = 0xFFu;                    /* (ext_ticks adds 1 for this tick: 0) */
    }
}

__attribute__((noinline)) static void pause_sound(seq_t *s, const seq_sink_t *o)   /* EXTERNAL waits: the 303 notes and the break stop */
{
    if (!s->playing)
        return;
    bass_and_brk_stop(s, o);
}

/* apply a new clock source (GLO > MIDI > CLOCK SOURCE), in the audio ISR */
static void clock_source(seq_t *s, const seq_sink_t *o)
{
    uint8_t m = s->clk_src;
    if (m > SEQ_CLK_EXT)
        m = SEQ_CLK_AUTO;
    s->clk_cur = m;
    s->clk_lost = 0;
    if (m == SEQ_CLK_INT) {                           /* the clock that came in is not used */
        s->ext_pending = 0;
        s->clk_lock = 0;                              /* MID-13/MID-15: INTERNAL owns no external clock */
        /* CLOCK SOURCE INTERNAL supersedes pending MIDI transport from the
         * previous mode, but must not cancel a newer local PLAY/STOP. */
        if (s->req_rt) {
            s->req_start = s->req_cont = s->req_rt = 0;
            s->req_prior_ticks = 0;
        }
        if (s->req_stop_rt)
            s->req_stop = s->req_stop_rt = 0;
        if (s->ext)
            switch_internal(s);
    } else if (m == SEQ_CLK_EXT && !s->ext) {         /* wait for the clock (AUTO: the clock or the timeout does it) */
        s->ext = 1;
        s->ext_bpm = s->bpm;                          /* no stale tempo */
        s->ext_period = 0;
        s->ext_nb = s->ext_bi = s->ext_q = 0;
        s->clk_lost = 1;
        if (s->playing)
            rephase(s);
        pause_sound(s, o);
    }
}

/* Observe the same rendered sample clock that advances the sequencer. No
 * timer, per-track playhead or MIDI-output timer is involved. The CPU0 audio
 * owner publishes one byte; the UI cannot mix phase and transport epochs.
 * External motion advances only on accepted clocks (never predicts lost ticks).
 * Internal tempo edits preserve fractional phase. This observer never changes
 * event partitioning, transport, outgoing MIDI or audio state. */
static void metro_advance(seq_t *s, uint32_t k)
{
    uint32_t period, phase;
    if (!s->playing || seq_clock_waiting(s) || (s->ext && s->metro_tick == 24u)) {
        s->metro_view = 0;
        return;
    }
    period = s->metro_period;
    if (!period || s->metro_bpm != seq_tempo(s)) {
        uint32_t next = seq_step_q8(s, RATE_16) * 4u;
        s->metro_phase = period ? (uint32_t)((float)s->metro_phase * (float)next / (float)period) : 0;
        if (!period) k = 0; /* accepted fresh start begins here, not before */
        s->metro_period = period = next;
        s->metro_bpm = seq_tempo(s);
    }
    if (s->ext) {
        phase = (uint32_t)s->metro_tick * period / 24u;
    } else {
        phase = s->metro_phase + (k << 8);
        while (phase >= period) phase -= period;
    }
    s->metro_phase = phase;
    s->metro_view = (uint8_t)(1u + phase * 32u / period);
}

void seq_advance(seq_t *s, uint32_t k, const seq_sink_t *o)
{
    int t, guard;
    uint32_t dq = k << 8;
    for (t = 0; t < NBASS; t++)
        if (s->rec_bass[t].active && (s->req_stop || s->req_start ||
            (!((s->rec_mask | s->rec_hold_mask) & (1u << t)) ||
             s->rec_bass[t].pat != s->ppat[TRK_BASS0 + t] || bpart(s, t)->dir >= DIR_PINGPONG)))
            seq_rec_cancel(s, t);
    if (s->ext_since < 2u * FS)   /* all modes: long idle must not wrap into a fake short tick */
        s->ext_since += k;
    s->ext_now += k;
    for (t = 0; t < NBASS; t++)
        if (s->bass_out_valid[t] && (!s->send_notes || s->ch[TRK_BASS0 + t] != s->bass_out_ch[t]))
            bass_midi_flush(s, t, o);    /* direct channel/settings edits cannot strand the old MIDI note */
    if (s->clk_cur != s->clk_src)
        clock_source(s, o);
    if (s->clk_lock && s->ext_now - s->clk_lock_at > SEQ_LOCK_T)
        s->clk_lock = 0;                              /* that input sends nothing: any input can get the clock */
    if (s->clk_cur == SEQ_CLK_INT)
        s->ext_pending = 0;
    if (s->ext_pending) {
        if (!s->ext && s->playing)                    /* playing on the internal clock: the first tick */
            rephase(s);                               /* is tick 0 of the step that plays (no step now) */
        s->ext = 1;
        s->clk_lost = 0;
    }
    else if (s->ext && s->ext_since > FS / 2u) {    /* clock gone for 0.5 s */
        if (s->clk_cur != SEQ_CLK_EXT)
            to_internal(s);                           /* back to internal */
        else if (!s->clk_lost) {                      /* EXTERNAL: pause, keep the place, wait for the clock */
            s->clk_lost = 1;
            clock_lost(s);
            pause_sound(s, o);
        }
    }
    if (s->req_stop) {                                /* (a Start after the Stop stays: seq_stop) */
        uint8_t rt = s->req_stop_rt;
        s->req_stop = 0;
        s->req_stop_rt = 0;
        if (s->playing)
            do_stop(s, o, rt);
    }
    if (s->req_start || s->req_cont) {
        uint8_t rt = s->req_rt;
        s->req_rt = 0;
        /* PLAY started X0X less than one step ago, and a MIDI Start or Continue comes (the host answers the
         * PLAY note, MID-14): X0X already plays step 1, so it does not start again (no second step 1) */
        if (rt && s->playing && s->start_local &&
            s->ext_now - s->start_at < (seq_step_q8(s, part_rate(s, TRK_DRUM)) >> 8))
            s->req_start = s->req_cont = 0;
        else {
            /* MIDI packets in one audio block may bracket Start/Continue.
             * Count only ticks after an accepted request for its new phase.
             * An ignored Loopy PLAY echo must retain every queued tick. */
            s->ext_pending = s->ext_pending >= s->req_prior_ticks
                ? s->ext_pending - s->req_prior_ticks : 0;
            if (s->req_start) {
                s->req_start = 0;
                do_start(s, 1, o, rt);
            }
            if (s->req_cont) {
                s->req_cont = 0;
                do_start(s, 0, o, rt);
            }
            s->start_local = (uint8_t)!rt;
            s->start_at = s->ext_now;
        }
    }
    s->midi_req = 0;                                  /* used only by the requests above */
    if (s->ext_pending)
        ext_ticks(s);
    metro_advance(s, k);
    if (!s->playing) {
        if (!s->ext)
            s->clk_to_next = 0;
        for (t = 0; t < NTRACKS; t++)                /* stopped: a cue takes effect at once */
            if (s->pcue[t] < NPAT) {
                s->ppat[t] = s->pcue[t];
                s->pcue[t] = 0xFF;
            }
        return;
    }
    for (t = 0; t < NTRACKS; t++) {                 /* move time */
        seq_track_t *tr = &s->t[t];
        if (tr->to_next != NEVER)
            tr->to_next = tr->to_next > dq ? tr->to_next - dq : 0;
        if (tr->to_off)
            tr->to_off = tr->to_off > dq ? tr->to_off - dq : 1;   /* 1: due, still "set" */
    }
    for (t = 0; t < NBASS; t++)
        if (s->bass_slide_off[t])
            s->bass_slide_off[t] = s->bass_slide_off[t] > dq ? s->bass_slide_off[t] - dq : 1;
    if (!s->ext && s->send_clock)
        s->clk_to_next = s->clk_to_next > dq ? s->clk_to_next - dq : 0;
    /* fire what is due; the drum part first, since its wrap may switch the pattern */
    for (guard = 0; guard < 8; guard++) {
        int fired = 0;
        for (t = 0; t < NTRACKS; t++) {
            seq_track_t *tr = &s->t[t];
            if (tr->to_off && tr->to_off < 256u) {    /* gate falls (before a new step at the same time) */
                bass_release(s, t - TRK_BASS0, o);
                fired = 1;
            }
            if (tr->to_next < 256u) {
                uint32_t ch = fire_step(s, t, o);
                if (ch)
                    restart(s, ch);                   /* a part's new pattern starts on step 1 */
                fired = 1;
            }
        }
        if (!fired)
            break;
    }
    for (t = 0; t < NBASS; t++)
        if (s->bass_slide_off[t] && s->bass_slide_off[t] < 256u)
            bass_slide_midi_off(s, t, o);
    if (!s->ext && s->send_clock && s->clk_to_next < 256u) {
        midi(o, 0xF8, 0, 0);
        s->clk_to_next += seq_step_q8(s, RATE_16) / 6u;           /* 24 ppqn */
    }
}

/* Publish the request type last: seq_advance must see its matching origin.
 * Start and Continue share the same setup; cont selects which flag is written last.
 * noinline: one body for seq_start / seq_continue / MIDI RT (else each site inlines). */
__attribute__((noinline)) static void request_play(seq_t *s, int remote, int cont)
{
    s->req_prior_ticks = s->ext_pending; /* clocks before this request belong to the older epoch */
    s->req_rt = (uint8_t)remote;
    if (cont) {
        s->req_start = 0;
        s->req_cont = 1; /* type last */
    } else {
        s->req_cont = 0;
        s->req_start = 1; /* type last */
    }
}
static void request_start(seq_t *s, int remote) { request_play(s, remote, 0); }
static void request_continue(seq_t *s, int remote) { request_play(s, remote, 1); }
void seq_start(seq_t *s) { request_start(s, 0); }
void seq_stop(seq_t *s)                       /* a Stop cancels an earlier Start or Continue, not a later one */
{
    s->req_start = s->req_cont = s->req_rt = 0;
    s->req_stop = 1;
    s->req_stop_rt = 0; /* local Stop supersedes any queued remote Stop */
}
void seq_continue(seq_t *s) { request_continue(s, 0); }
void seq_ext_clock(seq_t *s) { s->ext_pending++; }
int seq_midi_rt(seq_t *s, uint8_t st)
{
    int internal = s->clk_src == SEQ_CLK_INT;
    switch (st) {
    case 0xF8: if (!internal) seq_ext_clock(s); return 1;
    case 0xFA: if (!internal) request_start(s, 1); return 1;
    case 0xFB: if (!internal) request_continue(s, 1); return 1;
    case 0xFC: if (!internal) {
        seq_stop(s);
        s->req_stop_rt = 1; /* preserve remote Stop origin until audio apply */
    } return 1;
    default: return 0;
    }
}
/* MID-15: Clock, Start, Continue, Stop and Song Position of one input only. Called before seq_midi_rt, in the same context
 * as seq_advance. The order of the messages decides when two inputs send at the same time. */
int seq_clk_take(seq_t *s, uint8_t st, uint32_t src)
{
    uint8_t me;
    if (st != 0xF8u && st != 0xF2u && (st < 0xFAu || st > 0xFCu))
        return 1;
    /* Packet origins 0/1/2 are USB/Bluetooth/TRS. Origin 3 is reserved.
     * Reject it before narrowing src+1 to uint8_t: wrapped values can alias a real owner. */
    if (src > 2u)
        return 0;
    me = (uint8_t)(src + 1u);
    if (s->clk_src == SEQ_CLK_INT) {                  /* seq_midi_rt drops them */
        s->clk_lock = 0;
        return 1;
    }
    if (s->clk_lock != me) {
        if (s->clk_lock && !(s->clk_stop && (st == 0xFAu || st == 0xFBu) &&
                             s->ext_now - s->clk_stop_at >= SEQ_LOCK_T))
            return 0;                                 /* another input has the clock */
        if (st == 0xFCu || st == 0xF2u)
            return 1;                                 /* no input has the clock: a Stop or a Song Position gets none */
        if (s->clk_last && s->clk_last != me) {      /* another input: the tempo measure starts again, */
            /* Discard unrendered clocks from the old source before accepting the
             * new source's tick, or one audio block can advance twice. */
            s->ext_pending = 0;                       /* queued ticks belong to the previous input */
            s->req_prior_ticks = 0;
            s->ext_nb = s->ext_bi = s->ext_q = 0;     /* from the tempo now (no gap in the beat ring) */
            s->ext_skip = 1;                          /* (the first ticks give no period) */
        }
        s->clk_lock = s->clk_last = me;
        s->clk_stop = 0;
    }
    if (st == 0xF2u)
        return 1;                                     /* Song Position of the input with the clock */
    if (st == 0xFCu) {
        s->clk_stop = 1;
        s->clk_stop_at = s->ext_now;
    } else {
        if (st != 0xF8u)
            s->clk_stop = 0;
        s->clk_lock_at = s->ext_now;
    }
    return 1;
}
void seq_clk_drop(seq_t *s, uint32_t src)
{
    if (s->clk_lock == src + 1u) {
        s->clk_lock = 0;                              /* its link ended: any input can get the clock now */
        s->ext_pending = 0;                           /* discard queued ticks from the disconnected owner */
        s->req_prior_ticks = 0;                       /* the dropped clock epoch cannot consume new-source ticks */
    }
}
int seq_clock_waiting(const seq_t *s)
{
    return s->clk_cur == SEQ_CLK_EXT && s->playing && s->ext_since > FS / 2u;
}
X0X_COLD void seq_cue(seq_t *s, int p)
{
    int t;
    if (p >= 0 && p < NPAT)
        for (t = 0; t < NTRACKS; t++)
            s->pcue[t] = (uint8_t)p;
}
X0X_COLD void seq_cue_part(seq_t *s, int t, int p)
{
    if (t >= 0 && t < NTRACKS && p >= 0 && p < NPAT)
        s->pcue[t] = (uint8_t)p;
}
X0X_COLD int seq_cue_of(const seq_t *s, int t) { return s->pcue[t] < NPAT ? s->pcue[t] : -1; }
int seq_next_step(seq_t *s, int t, int p) { return next_pos(s, t, p, 0); }
/* the step a live hit now records on: the nearest step. That is the step that plays, or the next one
 * after half of the step (samples on the internal clock, ticks on an external clock; on an external
 * clock also a next step that its tick armed and that did not play yet). Before a part's first step
 * after PLAY or Start: its first step. */
int seq_rec_step(seq_t *s, int t)
{
    const seq_track_t *tr = &s->t[t];
    int rate = part_rate(s, t), late;
    if (!tr->started)
        return (is_bass(t) && bpart(s, t - TRK_BASS0)->dir == DIR_REV) ? seq_part_len(s, t) - 1 : 0;
    if (s->ext)
        late = tr->to_next != NEVER || (tr->ext_ticks != 0xFFu && tr->ext_ticks >= (TICKS_PER_STEP[rate] + 1u) / 2u);
    else {
        /* Record against the actual swung internal step duration, not an unswung half-step. */
        uint32_t L = seq_step_q8(s, rate), sw = swing_q8(s, rate, L);
        int np = next_pos(s, t, tr->pos, 0);
        uint32_t span = (np & 1) ? L + sw : L - sw;
        if (!(np & 1) && !(tr->pos & 1))   /* even -> even on an odd-length wrap: no swing */
            span = L;
        late = tr->to_next != NEVER && tr->to_next < span / 2u;
    }
    return late ? next_pos(s, t, tr->pos, 0) : tr->pos;
}
/* a live hit (voice v; 303: 0) recorded on step p: if p did not play yet on this pass, p does not sound
 * that voice when it plays next (the key sounded it). Once: the next step clears it. */
void seq_rec_skip(seq_t *s, int t, int p, int v)
{
    seq_track_t *tr = &s->t[t];
    if (tr->started && p == tr->pos)                  /* it played on this pass */
        return;
    if (tr->rec_skip_step != p || tr->rec_skip_pat != s->ppat[t])
        tr->rec_skip = 0;
    tr->rec_skip_step = (uint8_t)p;
    tr->rec_skip_pat = s->ppat[t];
    tr->rec_skip |= (uint16_t)(1u << v);
}
X0X_COLD void seq_chain(seq_t *s, int a, int b)
{
    /* Reject invalid endpoints before narrowing to uint8_t: an out-of-range
     * chain otherwise selects a non-existent pattern at the next bar. */
    if (a < 0 || a >= NPAT || b < 0 || b >= NPAT)
        return;
    s->chain_a = (uint8_t)a;
    s->chain_b = (uint8_t)b;
}


void seq_rec_cancel(seq_t *s, int b)
{
    seq_bass_rec_t *r = &s->rec_bass[b];
    r->gen++;
    r->own_ok = 0; /* the old press no longer owns a gate the sequencer may reopen */
    if (r->active)
        seq_rec_bass_end(s, b);
}

void seq_rec_bass_end(seq_t *s, int b)
{
    seq_bass_rec_t *r = &s->rec_bass[b];
    if (!r->active) return;
    bpart_t *bp = &s->pat[r->pat].bass[b];
    seq_track_t *tr = &s->t[TRK_BASS0 + b];
    uint32_t L = r->slot;
    uint32_t elapsed = s->ext_now - r->at;
    /* Clamp before Q8 conversion/multiply: stopped external clocks may be stale.
     * Slowest slot (20 BPM,8 ticks,+50% swing) is <=16934400 Q8;
     * slot*15+slot/2 fits uint32_t, so no 64-bit division helper is needed. */
    unsigned end = !r->entered ? 1 : r->entered == 2 || elapsed >= (L >> 8) ? 15 :
                   (unsigned)(((elapsed << 8) * 15u + L / 2u) / L);
    if (!end && r->last != r->first) {
        bp->step[r->last].flags = G_REST;
#if X0X_BASS_NOTE_SOUND
        seq_bass_sound_clear(s,b,r->pat,r->last);
#endif
        r->last = r->prev;
        end = 15; /* boundary belongs to previous slot, including reverse/wrap */
    }
    if (end < 1) end = 1;
    if (end > 15) end = 15;
    bstep_t *st = &bp->step[r->last];
    st->flags = (uint8_t)((st->flags & 15u) | (end << BS_END_SHIFT));
    r->active = 0;
    s->rec_dirty = 1;
    tr->to_off = 1; /* flush sequencer MIDI output at the actual live release */
}

void seq_rec_bass(seq_t *s, int b, int note, int velocity, int down, int src, int flags)
{
    seq_bass_rec_t *r = &s->rec_bass[b];
    if (!down) {
        if (r->active && r->note == note && r->src == src)
            seq_rec_bass_end(s, b);
        return;
    }
    if (!s->playing || !(s->rec_mask & (1u << b))) return;
    /* A cell may be visited repeatedly before the onset repeats. One endpoint
     * nibble cannot identify that occurrence. Refuse before any pattern write;
     * the accepted live edge still auditions through the engine. */
    if (bpart(s, b)->dir >= DIR_PINGPONG) {
        s->rec_refused = 1;
        return;
    }
    /* The flag alone is not proof. A context cancel bumps gen and clears own_ok,
     * so a later open DSP gate cannot slide from the cancelled note. */
    int owned = r->own_ok && r->own_gen == r->gen && r->own_src == (uint8_t)src;
    int overlap = (flags & SEQ_REC_LEGATO) && owned && r->active && r->src == src;
    int t = TRK_BASS0 + b, p = seq_rec_step(s, t);
    int old = r->last == p ? r->prev : r->last, oldpat = r->pat;
#if X0X_BASS_NOTE_SOUND
    if(seq_bass_sound_prepare(s,b,s->ppat[t],p)) {
        s->rec_refused=2; /* sound pool full or sound identity unavailable */
        return;
    }
    /* Preparation is the atomic admission check and already publishes sound.
     * A just-entered provisional tail can round back to the previous slot on
     * release. That tail is now the new onset: finalize the previous slot at
     * its full length without clearing the sound we just admitted. */
    if (r->active && r->pat == s->ppat[t] && r->last == p &&
        r->last != r->first && r->entered == 1) {
        uint32_t elapsed = s->ext_now - r->at, L = r->slot;
        if (elapsed < (L >> 8) && ((elapsed << 8) * 15u + L / 2u) / L == 0) {
            r->last = r->prev;
            r->entered = 2;
        }
    }
#endif
    seq_rec_bass_end(s, b);
    bpart_t *bp = bpart(s, b);
    if (overlap && oldpat == s->ppat[t] && old != p)
        bp->step[old].flags = (uint8_t)((bp->step[old].flags & 15u) | BS_SLIDE);
    bp->step[p].note = (uint8_t)note;
    bp->step[p].velocity = (uint8_t)velocity;
    bp->step[p].flags = (uint8_t)(G_NOTE | (flags & (BS_ACCENT | BS_SLIDE)) | 0xF0u);
    r->active = 1; r->pat = s->ppat[t]; r->first = r->last = r->prev = (uint8_t)p;
    r->note = (uint8_t)note; r->src = (uint8_t)src;
    s->rec_dirty = 1;
    r->entered = s->t[t].started && p == s->t[t].pos;
    r->at = s->ext_now; r->slot = bass_slot_q8(s, b, p);
    if (r->entered) {
        uint32_t L = bass_slot_q8(s, b, p), elapsed;
        if (s->ext) {
            elapsed = (uint32_t)s->t[t].ext_ticks * s->ext_period + (s->ext_since << 8);
            uint32_t sw = (p & 1) ? swing_q8(s, bp->rate, seq_step_q8(s, bp->rate)) : 0;
            elapsed = elapsed > sw ? elapsed - sw : 0;
        } else elapsed = s->t[t].to_next <= L ? L - s->t[t].to_next : 0;
        r->at -= elapsed >> 8;
    }
    seq_rec_skip(s, t, p, 0);
    s->t[t].to_off = 0;
    s->t[t].sounding = 1; /* tie/stop bookkeeping follows the live authoritative gate */
    s->t[t].held_note = (uint8_t)(note | (((flags & BS_SLIDE) || overlap) ? 0x80u : 0));
}

